L5_1 = {}
L5_1.m_CutScenKey_Talk = "SCAVENGER_DIVE50_END@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 3100011
L5_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "OPR_NPC_NULL_NULL"
L5_1.m_Talk_KOREA = "함선 무장 8할 소실! 다음 공격은 요격이 불가능합니다!"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "艦船武装8割消失！　次の攻撃は迎撃できません！"
L5_1.m_Talk_ENG = "It's lost eighty percent of its armament. We can't intercept any more attacks!"
L5_1.m_Talk_TWN = "艦船武裝有8成毀損！無法攔截下一次的攻擊！"
L5_1.m_Talk_THA = "เสียยุทธภัณฑ์ไป 80% เราสกัดกั้นการโจมตีไม่ได้อีกแล้ว!"
L5_1.m_Talk_VTN = "Nó bị mất 80% vũ khí. Chúng ta không thể đánh chặn bất kỳ cuộc tấn công nào nữa!"
L5_1.m_Talk_SCN = "舰船武装损失八成！无法拦截下次攻击！"
L5_1.m_Talk_DEU = "Verlust von 80 % der Bewaffnung! Wir können den nächsten Angriff nicht abfangen!"
L5_1.m_Talk_FRA = "Le blindage de la coque est détruit à 80 % ! La prochaine attaque nous sera fatale !"
L6_1 = {}
L6_1.m_CutScenKey_Talk = "SCAVENGER_DIVE50_END@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3100011
L6_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_HATE"
L6_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Crash = 20
L6_1.m_Talk_KOREA = "역시…… 연합 함대가 상대했을 때보다 더 강해졌어. "
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "やはり……連合艦隊が相手した時よりもさらに強くなっている。"
L6_1.m_Talk_ENG = "I knew it... It's gotten stronger since it fought the Coalition Fleet. "
L6_1.m_Talk_TWN = "果然……比那時候和聯合艦隊交手時變強許多！"
L6_1.m_Talk_THA = "กะแล้วเชียว... มันแข็งแกร่งขึ้นตั้งหลังจากที่สู้กับกองยานสนธิกำลัง"
L6_1.m_Talk_VTN = "Tôi biết mà... Nó trở nên mạnh hơn kể từ khi chiến đấu với Hạm Đội Liên Minh."
L6_1.m_Talk_SCN = "果然……比联合舰队对付它时变得更强了。 "
L6_1.m_Talk_DEU = "Ich habe es geahnt ... er ist noch stärker geworden als beim Kampf gegen die Allianzflotte."
L6_1.m_Talk_FRA = "J'en étais sûre... Cette chose est bien plus puissante que lors de son affrontement passé avec la Coalition. "
L7_1 = {}
L7_1.m_CutScenKey_Talk = "SCAVENGER_DIVE50_END@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 3100011
L7_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "급조한 부품으로 어떻게 저만큼 성능을 향상시켰지? 정말로 기계가 진화라도 하는 건가?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "急造した部品でどうやってあんなに性能を向上させられた？　本当に機械が進化でもするのか？"
L7_1.m_Talk_ENG = "How did they improve its performance so much with improvised components? Can that machine really evolve?"
L7_1.m_Talk_TWN = "是怎麼用粗製濫造的零件，把性能提升到這個程度的？真的是機械進化嗎？"
L7_1.m_Talk_THA = "พวกนั้นปรับปรุงสมรรถนะของมันด้วยส่วนประกอบที่ไม่ได้เตรียมการมาก่อนได้ยังไง? เครื่องจักรนั่นมีวิวัฒนาการได้จริงๆ เหรอ?"
L7_1.m_Talk_VTN = "Làm thế nào chúng cải thiện hiệu suất của nó nhiều như vậy với các bộ phận ngẫu nhiên chứ? Cỗ máy đó thực sự có thể tiến hóa ư?"
L7_1.m_Talk_SCN = "究竟是怎么用赶造的零件，把性能提高到这种程度的？莫非机械真的会进化？"
L7_1.m_Talk_DEU = "Wie haben sie ihn mit improvisierten Komponenten derart verbessern können? Ist diese Maschine tatsächlich der Evolution fähig?"
L7_1.m_Talk_FRA = "Comment ont-ils fait pour décupler ses performances avec de la simple ferraille ? Cette machine... elle a vraiment évolué ?"
