L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "室長！　最後の護衛艦もやられました！　これ以上は危険です！"
L9_1.m_Talk_ENG = "Chief! Our last escort ship went down! We're too vulnerable right now!"
L9_1.m_Talk_TWN = "室長！最後一艘護衛艦也快不行了！這樣下去會有危險！"
L9_1.m_Talk_THA = "ผู้อำนวยการ! ยานลำเลียงลำสุดท้ายของเราร่วงแล้ว! ตอนนี้เราอ่อนแอเกินไป!"
L9_1.m_Talk_VTN = "Giám đốc! Tàu hộ tống cuối cùng của chúng ta đã bị hạ! Hiện giờ chúng ta bị thương quá mức!"
L9_1.m_Talk_SCN = "室长！最后的护卫舰也毁了！现在这样很危险！"
L9_1.m_Talk_DEU = "Direktorin! Unser letztes Begleitschiff ist untergegangen! Mehr geht nicht mehr!"
L9_1.m_Talk_FRA = "Madame ! Notre dernier vaisseau d'escorte est à terre ! Nous sommes complètement vulnérables !"
