L11_1 = "알파트릭스가 관리국과 손잡고 날 제압하는 데 사용했던 기술이지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "アルファトリックスが管理局と手を組んで私を制圧する時に使っていた技術だ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Alphatrix used that technology to subdue me in concert with the Administration."
L10_1.m_Talk_ENG = L11_1
L11_1 = "就是阿爾法崔克斯和管理局聯手壓制我時，使用過的技術對吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "อัลฟาทริกซ์ใช้เทคโนโลยีนั้นปราบฉันในการปะทะกับองค์การบริหารโลก"
L10_1.m_Talk_THA = L11_1
L11_1 = "Alphatrix đã sử dụng công nghệ đó với Cục Quản Lý để khuất phục tôi."
L10_1.m_Talk_VTN = L11_1
L11_1 = "是阿尔法崔克斯和管理局联手对付我时使用的技术吧。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Das ist eine Technologie von Alphatrix und der Administration, mit der ich besiegt wurde."
L10_1.m_Talk_DEU = L11_1
L11_1 = "À l'époque, c'est la technologie qui avait permis à l'Administration de me vaincre, en s'associant à Alphatrix..."
L10_1.m_Talk_FRA = L11_1
