L11_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L12_1 = "일반적인 기계였다면 방금 그 공격으로 기동 불가 상태에 처했을 거다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "一般的な機械であれば先ほどの攻撃で起動不可状態に陥ったはずだ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "An ordinary machine would have been frozen by that attack."
L11_1.m_Talk_ENG = L12_1
L12_1 = "要是普通的機械受到剛剛的攻擊，肯定會無法運作。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เครื่องจักรรรมดาคงขยับไม่ได้ถ้าถูกโจมตีแบบนั้น"
L11_1.m_Talk_THA = L12_1
L12_1 = "Một cỗ máy bình thường sẽ bị đóng băng bởi đòn tấn công đó."
L11_1.m_Talk_VTN = L12_1
L12_1 = "一般的机械受到刚才的攻击，应该会陷入不能动弹的状态。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Jede andere Maschine wäre durch den Angriff von eben erstarrt."
L11_1.m_Talk_DEU = L12_1
L12_1 = "N'importe quelle machine ordinaire aurait été neutralisée par cette attaque, oui."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SCAVENGER_DIVE50_END@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3100011
L12_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L13_1 = "그리고 나를 일반적인 기계라고 판단한 것이, 너의 실책이다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そして私を一般的な機械と判断したことが、お前の失策だ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But I'm not ordinary. Thinking like that was your mistake."
L12_1.m_Talk_ENG = L13_1
L13_1 = "但如果妳以為我是普通的機械，那妳可就大錯特錯囉。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่ฉันไม่ธรรมดา คิดซะว่านั่นเป็นความผิดพลาดของแกก็แล้วกัน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhưng ta không phải là người thường. Cô đã sai khi đánh giá ta như vậy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "然而把我看作一般的机械，是你的失误。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dein Fehler war es, mich für eine gewöhnliche Maschine zu halten."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Mais je ne suis pas une machine ordinaire. Tu m'as sous-estimé, c'était une erreur."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SCAVENGER_DIVE50_END@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3100011
L13_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L14_1 = "나는 이미, 극복했으니 말이다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私はすでに、克服している。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I already have overcome that weakness."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我已經…克服了！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันก้าวผ่านจุดอ่อนนั้นได้แล้ว"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ta đã vượt qua điểm yếu đó lâu rồi."
L13_1.m_Talk_VTN = L14_1
L14_1 = "因为，我已经克服这个弱点了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich habe diese Schwäche nämlich bereits überwunden."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Cette faiblesse, je l'ai surmontée."
L13_1.m_Talk_FRA = L14_1
