L16_1 = "장갑 증량. 배선 구조 교체. 방벽을 통한 전자기파 차폐."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "装甲増量。配線構造の取り替え。防壁による電磁波遮蔽。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Increased armor. Updated wiring system. Anti-EMP barrier."
L15_1.m_Talk_ENG = L16_1
L16_1 = "裝甲增量、重新替換線路、透過屏障遮蔽電磁波。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เพิ่มเกราะ อัปเดตระบบสายไฟ สร้างบาเรียต้าน EMP"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tăng cường giáp bị. Đã cập nhật hệ thống dây. Hàng rào chống EMP."
L15_1.m_Talk_VTN = L16_1
L16_1 = "通过装甲增量、更换配线结构，还有屏障，屏蔽掉电磁波。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Verstärkte Rüstung. Ein aktualisiertes Verkabelungssystem. Eine Anti-EMP-Barriere."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Amélioration du blindage. Remplacement de la structure de cablage. Barrière anti-IEM."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SCAVENGER_DIVE50_END@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3100011
L16_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L17_1 = "나는 너희가 내게 바치는 기술의 산물을 통해 매순간 결함을 극복하고 강해지지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "私はお前たちが私に捧げる技術の産物によって、毎瞬間欠陥を克服して強くなる。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Every time you attack me with a new technology, I overcome my weaknesses and grow stronger."
L16_1.m_Talk_ENG = L17_1
L17_1 = "藉由你們在我身上進行研究後留下的結果，我每時每刻都在克服缺點不斷變強。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ทุกครั้งที่แกใช้เทคโนโลยีใหม่โจมตีฉัน ฉันจะก้าวผ่านจุดอ่อนของตัวเองและแข็งแกร่งขึ้น"
L16_1.m_Talk_THA = L17_1
L17_1 = "Mỗi khi cô tấn công ta bằng một công nghệ mới, ta đều khắc phục được điểm yếu của mình và phát triển mạnh mẽ hơn."
L16_1.m_Talk_VTN = L17_1
L17_1 = "通过你们献给我的技术产物，我每时每刻都在克服缺陷，变得更强大。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Durch die Errungenschaften der Technologien, die ihr mir opfert, überwinde ich meine Schwächen und werde stärker."
L16_1.m_Talk_DEU = L17_1
L17_1 = "À chaque fois que tu m'attaques avec de nouvelles technologies, cela me permet de surmonter mes faiblesses pour devenir plus fort."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SCAVENGER_DIVE50_END@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
