L17_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L18_1 = "그렇기에 나는, 진화 그 자체다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "それ故私は、進化そのものだ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I'm evolution itself."
L17_1.m_Talk_ENG = L18_1
L18_1 = "因此，我本身就是進化！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ฉันคือวิวัฒนาการ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ta tự tiến hóa."
L17_1.m_Talk_VTN = L18_1
L18_1 = "所以，我，就是进化本身。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Deshalb bin ich die Evolution, wie sie leibt und lebt."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Autrement dit, je suis une incarnation de l'évolution."
L17_1.m_Talk_FRA = L18_1
