L21_1 = "SCAVENGER_DIVE50_END@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L20_1.m_CutScenProcessKey = 70
L20_1.m_CutScenID = 3100011
L20_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L21_1 = "퓨처 앳 워는 현대의 한계를 뛰어넘어 미래의 기술을 연구하던 곳이지만……"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "フューチャーアットウォーは現代の限界を超えて未来の技術を研究していましたが……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Future-at-War used to study futuristic technologies to surpass the limits of the present."
L20_1.m_Talk_ENG = L21_1
L21_1 = "天啟兵器是一個突破現代極限，研究未來技術的地方……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฟิวเจอร์-แอท-วอร์เคยศึกษาเทคโนโลยีโลกอนาคตเพื่อก้าวผ่านขีดจำกัดของปัจจุบัน"
L20_1.m_Talk_THA = L21_1
L21_1 = "Chiến Tranh Tương Lai từng nghiên cứu các công nghệ mang tính tương lai để vượt qua giới hạn của hiện tại."
L20_1.m_Talk_VTN = L21_1
L21_1 = "天启兵器是超越现代局限，研究未来技术的地方……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Bei Future-at-War wurden Zukunftstechnologien erforscht, die über die Grenzen der Moderne hinausgehen ..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Que Future-at-War essayait de développer des technologies futuristes capables de repousser les limites actuelles."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "SCAVENGER_DIVE50_END@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3100011
L21_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L22_1 = "그 중에서도 유달리 먼 곳만 바라보던 과학자가 한 분 계셨다고요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "その中でも、さらに先を見越していた科学者が一人いたそうです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "And one of its scientists looked further than anyone else."
L21_1.m_Talk_ENG = L22_1
L22_1 = "在那裡，有一位野心特別大的科學家。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "และนักวิทยาศาสตร์ของพวกเขาคนหนึ่งมองไปไกลกว่าคนอื่นๆ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Và một trong những nhà khoa học của họ đã nhìn xa hơn bất cứ ai khác."
L21_1.m_Talk_VTN = L22_1
L22_1 = "但其中有一位比任何人看得都更加远的科学家。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Doch ein Forscher solle besonders weit in die Ferne geschaut haben."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Une scientifique, en particulier, avait des ambitions visionnaires..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
