L23_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L24_1 = "지금 그 모습이 된 건…… 저희 숙부님 때문인가요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "今その姿になっているのは……叔父様が原因でしょうか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Did you become what you are now because of my uncle?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "妳現在會變成這樣……是因為我叔叔的關係嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ที่คุณเป็นแบบทุกวันนี้ได้เพราะลุงของฉันเหรอ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô đã trở thành như bây giờ vì bác của tôi ư?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "你现在变成这副样子……是因为我叔父吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Sind Sie zu dem geworden, was Sie sind, wegen meines Onkels ...?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Est-ce mon oncle qui est responsable de ce que vous êtes devenue ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SCAVENGER_DIVE50_END@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3100011
L24_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L25_1 = "아니."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "いや。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "No."
L24_1.m_Talk_ENG = L25_1
L25_1 = "不。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เปล่า"
L24_1.m_Talk_THA = L25_1
L25_1 = "Không."
L24_1.m_Talk_VTN = L25_1
L25_1 = "不是。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Nein."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Non."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SCAVENGER_DIVE50_END@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3100011
L25_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L26_1 = "그 자는 과거에나 지금이나 그럴 능력이 없다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "その者は過去も今もそのような実力はない。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "He was never good enough to have any influence over me."
L25_1.m_Talk_ENG = L26_1
L26_1 = "無論是過去或現在，他都沒有這樣的能力。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "หมอนั่นไม่เคยดีพอที่จะมีอิทธิพลใดๆ ต่อฉันเลย"
L25_1.m_Talk_THA = L26_1
L26_1 = "Hắn không đủ đô để có bất kỳ ảnh hưởng nào đối với ta."
L25_1.m_Talk_VTN = L26_1
L26_1 = "不管是过去还是现在，他都没有那样的能力。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Dieser Mensch hat nach wie vor nicht die Fähigkeit dazu."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Il n'en a pas, et n'aura jamais, les capacités suffisantes pour ça."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "SCAVENGER_DIVE50_END@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3100011
L26_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L27_1 = "날 붙잡아 둔 채 샘플로 이용했으면서도 실패한 모조품이나 만드는 게 고작이었지."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "私を捕らえてサンプルとして利用しながらも、失敗した模造品を作るのが精一杯だった。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "He held me prisoner and used me as a testing sample, but all he could create were bad knock-offs."
L26_1.m_Talk_ENG = L27_1
L27_1 = "他把我抓來當樣品，卻只是製造出失敗的仿冒品。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เขาขังฉันไว้และใช้ฉันเป็นตัวอย่างทดลอง แต่เขาก็ทำได้แค่ของเลียนแบบห่วยๆ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Hắn giam giữ và sử dụng ta như một vật mẫu thử nghiệm, nhưng tất cả những gì hắncó thể tạo ra đều là hàng nhái rởm."
L26_1.m_Talk_VTN = L27_1
L27_1 = "他困住我，不过是拿我当样本，制造出了很多失败的仿制品而已。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Obwohl er mich eingesperrt und als Probe benutzt hat, konnte er nur gescheiterte Nachahmungen herstellen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Il m'a gardée en captivité et m'a utilisée comme sujet d'expérience pour toutes sortes de recherches mais tout ce qu'il a créé, ce sont des copies ratées."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "SCAVENGER_DIVE50_END@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3100011
L27_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L28_1 = "이건, 오로지 나의 힘으로 이룩한 결과다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "これは、己の力で成し遂げた成果だ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I've accomplished this on my own."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我現在這個樣子，是唯有我有的力量才能產生的結果。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันทำสิ่งนี้สำเร็จได้ด้วยตัวฉันเอง"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ta đã tự mình hoàn thiện."
L27_1.m_Talk_VTN = L28_1
L28_1 = "现在这个结果，是凭我一己之力完成的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Das hier habe ich aus eigener Kraft erreicht, ich allein."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ce corps que tu as devant les yeux, c'est mon œuvre."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SCAVENGER_DIVE50_END@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3100011
L28_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L29_1 = "그 과정에서 인간성과 함께 많은 것들을 내려놓아야 했지만……"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "その過程で人間性とともに多くのものを手放さなければならなかったが……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "During the process, I had to give up many things, including my humanity, but..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "雖然在那樣的過程裡，必須拋棄掉許多人性面的東西……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ระหว่างกระบวนการนั้น ฉันต้องสละอะไรหลายอย่าง รวมถึงความเป็นมนุษย์ของตัวเองด้วย แต่ว่า..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Trong quá trình này, ta đã phải từ bỏ nhiều thứ, kể cả nhân tính của mình, nhưng..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "虽然这个过程中需要放下人性和很多东西……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Allerdings musste ich in dessen Verlauf meine Menschlichkeit und vieles andere aufgeben ..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Pour arriver jusqu'ici, j'ai dû faire de nombreux sacrifices. J'ai même du dire adieu à mon humanité..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SCAVENGER_DIVE50_END@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3100011
L29_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L30_1 = "충분히 그럴 만한 가치가 있었지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "それだけの価値があった。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "It was worth the sacrifice."
L29_1.m_Talk_ENG = L30_1
L30_1 = "但這完全是有價值的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "มันเป็นการเสียสละที่คุ้มค่า"
L29_1.m_Talk_THA = L30_1
L30_1 = "Sự hy sinh đó rất xứng đáng."
L29_1.m_Talk_VTN = L30_1
L30_1 = "但完全有这个价值。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Trotzdem war es das wert."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Mais je ne regrette absolument rien."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
