L32_1 = "FX_CUTSCEN_NOISE"
L31_1.m_StartFXSoundName = L32_1
L32_1 = "LENA_COFFIN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "통신이 회복됐습니다!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "通信が回復しました！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Communications back online!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "恢復通訊了！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ระบบสื่อสารกลับมาทำงานแล้ว!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hệ thống liên lạc đã trực tuyến trở lại!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "通信恢复了！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Die Kommunikation ist wieder online!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "La communication est restaurée !"
L31_1.m_Talk_FRA = L32_1
