L33_1 = "SCAVENGER_DIVE50_END@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3100011
L32_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "FX_CUTSCEN_NOISE"
L32_1.m_StartFXSoundName = L33_1
L33_1 = "XIAOLIN_ALT_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "<color=#ffd34c>신지아 씨, 들리나요?</color>"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "<color=#ffd34c>ヒメノ・ユイさん、聞こえますか？</color>"
L32_1.m_Talk_JPN = L33_1
L33_1 = "<color=#ffd34c>Jia, can you hear me?</color>"
L32_1.m_Talk_ENG = L33_1
L33_1 = "<color=#ffd34c>沈佳小姐，妳有聽到嗎？</color>"
L32_1.m_Talk_TWN = L33_1
L33_1 = "<color=#ffd34c>เจีย! ได้ยินมั้ย?</color>"
L32_1.m_Talk_THA = L33_1
L33_1 = "<color=#ffd34c>Jia, cô có  nghe thấy tôi không?</color>"
L32_1.m_Talk_VTN = L33_1
L33_1 = "<color=#ffd34c>沈佳，听得见吗？</color>"
L32_1.m_Talk_SCN = L33_1
L33_1 = "<color=#ffd34c>Shin Jia, hören Sie mich?</color>"
L32_1.m_Talk_DEU = L33_1
L33_1 = "<color=#ffd34c>Shin Jia, vous me recevez ?</color>"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SCAVENGER_DIVE50_END@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3100011
L33_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "XIAOLIN_ALT_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "<color=#ffd34c>조금만 버티세요. 지금 가고 있습니다.</color>"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "<color=#ffd34c>もう少し耐えてください。今向かっています。</color>"
L33_1.m_Talk_JPN = L34_1
L34_1 = "<color=#ffd34c>Hang on just a little longer. We're coming.</color>"
L33_1.m_Talk_ENG = L34_1
L34_1 = "<color=#ffd34c>妳再撐一下，我們正趕過去！</color>"
L33_1.m_Talk_TWN = L34_1
L34_1 = "<color=#ffd34c>อดทนอีกหน่อยนะ เรากำลังไป</color>"
L33_1.m_Talk_THA = L34_1
L34_1 = "<color=#ffd34c>Hãy chờ thêm một lát thôi. Chúng tôi đang đến đây.</color>"
L33_1.m_Talk_VTN = L34_1
L34_1 = "<color=#ffd34c>再坚持一下，我们正在赶往你那边。</color>"
L33_1.m_Talk_SCN = L34_1
L34_1 = "<color=#ffd34c>Halten Sie etwas durch. Wir sind auf dem Weg.</color>"
L33_1.m_Talk_DEU = L34_1
L34_1 = "<color=#ffd34c>Tenez bon, nous sommes en route !</color>"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
