L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3100011
L38_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "YOOJIN_ALT_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "<color=#ffd34c>이 자식들 완전 끈질기네! 저리 안 비켜?!</color>"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "<color=#ffd34c>こいつら、しつこいな！　どけよ、こら！</color>"
L38_1.m_Talk_JPN = L39_1
L39_1 = "<color=#ffd34c>These jerks are so persistent! Just go away!</color>"
L38_1.m_Talk_ENG = L39_1
L39_1 = "<color=#ffd34c>這些傢伙有夠難纏的！都給我閃開啦！</color>"
L38_1.m_Talk_TWN = L39_1
L39_1 = "<color=#ffd34c>พวกบ้านี่ดื้อด้านน่าดู! ไปให้พ้น!</color>"
L38_1.m_Talk_THA = L39_1
L39_1 = "<color=#ffd34c>Những tên khốn ấy dai như đỉa! Cút đi!</color>"
L38_1.m_Talk_VTN = L39_1
L39_1 = "<color=#ffd34c>这帮家伙可真执着啊！滚开？！</color>"
L38_1.m_Talk_SCN = L39_1
L39_1 = "<color=#ffd34c>Diese Mistkerle sind hartnäckig! Aus dem Weg!</color>"
L38_1.m_Talk_DEU = L39_1
L39_1 = "<color=#ffd34c>Ces imbéciles sont vraiment collants ! Dégagez de là !</color>"
L38_1.m_Talk_FRA = L39_1
