L42_1 = "KIMSOBIN_ALT_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "<color=#ffd34c>쏘, 쏩니다! 이젠 어떻게 되도 몰라요!</color>"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "<color=#ffd34c>う、撃ちますよ！　もうどうなってもわかりませんよ！</color>"
L41_1.m_Talk_JPN = L42_1
L42_1 = "<color=#ffd34c>I-I'm going to shoot! Don't blame me for whatever happens!</color>"
L41_1.m_Talk_ENG = L42_1
L42_1 = "<color=#ffd34c>射…發射！死就死吧！</color>"
L41_1.m_Talk_TWN = L42_1
L42_1 = "<color=#ffd34c>ฉะ-ฉันจะยิงนะ! ถ้าเกิดอะไรขึ้นแล้วอย่ามาโทษฉันแล้วกัน</color>"
L41_1.m_Talk_THA = L42_1
L42_1 = "<color=#ffd34c>T-tôi sẽ bắn đấy! Đừng có trách tôi khi có bất kỳ điều gì xảy ra!</color>"
L41_1.m_Talk_VTN = L42_1
L42_1 = "<color=#ffd34c>我，我要发射了！受了什么伤可别怪我啊啊啊啊！</color>"
L41_1.m_Talk_SCN = L42_1
L42_1 = "<color=#ffd34c>I-ich schieße! Ich weiß jetzt auch nicht mehr weiter!</color>"
L41_1.m_Talk_DEU = L42_1
L42_1 = "<color=#ffd34c>J-je vais tirer ! Il ne faudra pas venir pleurer, après !</color>"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
