L45_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L46_1 = "<color=#ffd34c>아가씨!</color>"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>お嬢様！</color>"
L45_1.m_Talk_JPN = L46_1
L46_1 = "<color=#ffd34c>Miss Jia!</color>"
L45_1.m_Talk_ENG = L46_1
L46_1 = "<color=#ffd34c>小姐！</color>"
L45_1.m_Talk_TWN = L46_1
L46_1 = "<color=#ffd34c>คุณหนู!</color>"
L45_1.m_Talk_THA = L46_1
L46_1 = "<color=#ffd34c>Tiểu Thư!</color>"
L45_1.m_Talk_VTN = L46_1
L46_1 = "<color=#ffd34c>小姐！</color>"
L45_1.m_Talk_SCN = L46_1
L46_1 = "<color=#ffd34c>Fräulein!</color>"
L45_1.m_Talk_DEU = L46_1
L46_1 = "<color=#ffd34c>Mademoiselle !</color>"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "SCAVENGER_DIVE50_END@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3100011
L46_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L47_1 = "<color=#ffd34c>코핀 컴퍼니가 지원을 왔습니다! 복귀하지 않고 저희를 도우러 왔어요!</color>"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "<color=#ffd34c>コフィンカンパニーの応援が来ました！　戻らず助けに来てくれました！</color>"
L46_1.m_Talk_JPN = L47_1
L47_1 = "<color=#ffd34c>Coffin Company has arrived! Instead of leaving, it came to help us!</color>"
L46_1.m_Talk_ENG = L47_1
L47_1 = "<color=#ffd34c>科芬公司的人來了！他們沒有回去，他們來幫我們了！</color>"
L46_1.m_Talk_TWN = L47_1
L47_1 = "<color=#ffd34c>บริษัทคอฟฟินมาแล้ว! แทนที่จะกลับไป พวกเขามาช่วยเรา! </color>"
L46_1.m_Talk_THA = L47_1
L47_1 = "<color=#ffd34c>Công Ty Coffin đã tới! Thay vì rời đi, họ đã tới giúp chúng ta!</color>"
L46_1.m_Talk_VTN = L47_1
L47_1 = "<color=#ffd34c>科芬公司赶来支援了！她们没回去，回来帮我们了！</color>"
L46_1.m_Talk_SCN = L47_1
L47_1 = "<color=#ffd34c>Die Coffin Company ist zur Unterstützung hier! Sie sind nicht zurückgegangen, sondern sind hier, um zu helfen!</color>"
L46_1.m_Talk_DEU = L47_1
L47_1 = "<color=#ffd34c>La Compagnie Coffin est arrivée en renfort ! Ils sont venus nous aider !</color>"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "SCAVENGER_DIVE50_END@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3100011
L47_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L48_1 = "<color=#ffd34c>지금 스캐빈저와 교전하면서 아가씨가 계신 곳으로 이동 중입니다! 조금만 버티세요!</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "<color=#ffd34c>今スカベンジャーと交戦しながらお嬢様がいる場所に移動中です！　もう少しだけ耐えてください！</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "<color=#ffd34c>It's fighting its way through the Scavengers to get where you are. Hang on!</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "<color=#ffd34c>我正一邊和清道夫交戰，一邊前往小姐所在的地方！請妳再撐一下！</color>"
L47_1.m_Talk_TWN = L48_1
L48_1 = "<color=#ffd34c>พวกเขากำลังฝ่าพวกสคาเวนเจอร์เพื่อจะไปหาคุณ อดทนไว้ก่อนนะ!</color>"
L47_1.m_Talk_THA = L48_1
L48_1 = "<color=#ffd34c>Họ đang chiến đấu với Scavengers để đến chỗ tiểu thư. Cố cầm cự!</color>"
L47_1.m_Talk_VTN = L48_1
L48_1 = "<color=#ffd34c>目前正一边跟清道夫交战，一边往小姐你那边赶！你再坚持一下！</color>"
L47_1.m_Talk_SCN = L48_1
L48_1 = "<color=#ffd34c>Sie kämpfen gerade gegen die Scavenger und bewegen Sich in Ihre Richtung! Halten Sie durch!</color>"
L47_1.m_Talk_DEU = L48_1
L48_1 = "<color=#ffd34c>Au moment où je vous parle, ils se frayent un chemin à travers les rang ennemis pour rejoindre votre position. Vous devez tenir jusqu'à leur arrivée !</color>"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
