L50_1 = "SCAVENGER_DIVE50_END@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3100011
