L50_1 = "THEMA_SCAVANGER_02"
L49_1.m_StartBGMFileName = L50_1
L49_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L50_1 = "……죄송해요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ごめんなさい……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I'm sorry."
L49_1.m_Talk_ENG = L50_1
L50_1 = "很抱歉……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันขอโทษนะคะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi xin lỗi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "……对不起。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "... Es tut mir leid."
L49_1.m_Talk_DEU = L50_1
L50_1 = "... Je suis désolée."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SCAVENGER_DIVE50_END@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3100011
L50_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L51_1 = "어떤 사정이 있는지는 모르겠지만, 전 당신을 여기서 쓰러트리고 돌아가야겠어요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "どういう事情があるかわかりませんが、私はあなたをここで倒してから戻ります。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I don't know what story you have, but I must bring you down and go back."
L50_1.m_Talk_ENG = L51_1
L51_1 = "我不清楚妳有什麼樣的苦衷，但我必須在這裡打倒妳。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันไม่รู้ว่าคุณเจอเรื่องอะไรมา แต่ฉันต้องปราบคุุณแล้วกลับบ้าน"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi không biết chuyện ra sao, nhưng tôi phải hạ cô và quay trở lại."
L50_1.m_Talk_VTN = L51_1
L51_1 = "虽然不知道你有什么苦衷，但我必须在这里打倒你才能回去。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich weiß zwar nicht, welche persönlichen Gründe Sie antreiben, aber ich muss Sie hier und jetzt besiegen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Je ne connais pas votre histoire, mais je dois vous éliminer."
L50_1.m_Talk_FRA = L51_1
