L1_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L2_1 = "다른 분들께 폐를 끼치지 말라고, 할아버님께서 가르쳐 주셨거든요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "他の方々に迷惑はかけないようにと、お祖父様に教わったのです。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Grandfather said I should never burden others."
L1_1.m_Talk_ENG = L2_1
L2_1 = "因為我爺爺說，不能給別人添麻煩。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "คุณปู่เคยบอกว่าฉันไม่ควรเป็นภาระให้คนอื่น"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ông đã nói tôi không bao giờ nên trở thành gánh nặng cho những người khác."
L1_1.m_Talk_VTN = L2_1
L2_1 = "爷爷说过，不要给别人添麻烦的。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Großvater hat mich nämlich gelehrt, dass man anderen nicht zur Last fallen darf."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mon grand-père disait toujours : « Ne sois pas un fardeau pour les autres »."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
