L3_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L4_1 = "회장은 성공했군. 나와 다르게."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "会長は成功したな。私と違って。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "So, the Chairman succeeded. Unlike me."
L3_1.m_Talk_ENG = L4_1
L4_1 = "會長成功了呢！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แปลว่าประธานทำสำเร็จ ไม่เหมือนกับฉัน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Vậy là Chủ Tịch đã thành công. Không giống như ta."
L3_1.m_Talk_VTN = L4_1
L4_1 = "看来跟我不一样，会长成功了呢。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Der Vorsitzende war also erfolgreich. Anders als ich."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Le Président a donc réussi. Là où j'ai échoué..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
