L7_1 = "SCAVENGER_DIVE50_END@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3100011
L6_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L7_1 = "너희를 전멸시키는 건 아주 간단한 일이다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "お前たちを全滅させるのは、とても簡単なことだ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "It'd be easy to wipe you out right here and now."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我要把你們全殺光是輕而易舉的事。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "การจะกำจัดแกตอนนี้ ที่นี่เป็นเรื่องง่าย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cho cô bay màu ngay tại đây và ngay bây giờ thật dễ như ăn cháo."
L6_1.m_Talk_VTN = L7_1
L7_1 = "歼灭你们是很简单的事。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Euch auszumerzen, wäre ein Klacks."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Si je le voulais, je pourrais te supprimer ici et maintenant."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SCAVENGER_DIVE50_END@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3100011
L7_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L8_1 = "하지만…… 어린 네가 앞으로 어떤 진화를 이루어낼지 흥미가 생기는군."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "しかし……幼いお前がこれからどういう進化を成し遂げるのか興味が湧いた。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "But... I'm interested in seeing how much you can evolve as a young human."
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過……我很好奇，現在還年幼的妳，之後會進化成什麼樣子呢？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่... ฉันอยากรู้ว่าแกจะวิวัฒนาการได้แค่ไหนในฐานะมนุษย์คนหนึ่ง"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nhưng... ta rất muốn xem cô có thể tiến hóa như thế nào khi còn trẻ."
L7_1.m_Talk_VTN = L8_1
L8_1 = "不过……我突然很好奇，年幼的你以后会完成怎样的进化呢？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Aber ... ich bin neugierig, welche Evolution du in Zukunft erringen wirst, da du noch jung bist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Cependant... Je suis curieuse de voir ton évolution, en tant que jeune humaine."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
