L11_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L12_1 = "자비는 한 번뿐이다. "
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "慈悲は一度だけだ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I won't be merciful again. "
L11_1.m_Talk_ENG = L12_1
L12_1 = "慈悲可只有一次。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันจะไม่ใจดีแบบนี้อีก"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ta sẽ không khoan nhượng nữa."
L11_1.m_Talk_VTN = L12_1
L12_1 = "我的慈悲只会有一次。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Gnade zeige ich nur einmal."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Cette chance, je ne te la donnerai pas deux fois. "
L11_1.m_Talk_FRA = L12_1
