L23_1.m_CharStrID = "OPR_NPC_NULL_NULL"
L24_1 = "<color=#ffd34c>찾았습니다! 생명반응 확인!</color>"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "<color=#ffd34c>見つけました！　生命反応確認！</color>"
L23_1.m_Talk_JPN = L24_1
L24_1 = "<color=#ffd34c>Found her! Vital signs confirmed!</color>"
L23_1.m_Talk_ENG = L24_1
L24_1 = "<color=#ffd34c>找到了！確認到生命反應！</color>"
L23_1.m_Talk_TWN = L24_1
L24_1 = "<color=#ffd34c>เจอแล้ว! ยืนยันสัญญาณชีพ!</color>"
L23_1.m_Talk_THA = L24_1
L24_1 = "<color=#ffd34c>Đã tìm thấy cô ấy! Xác nhận các tín hiệu sống sót!</color>"
L23_1.m_Talk_VTN = L24_1
L24_1 = "<color=#ffd34c>找到了！生命反应确认！</color>"
L23_1.m_Talk_SCN = L24_1
L24_1 = "<color=#ffd34c>Gefunden! Lebenssignale vorhanden!</color>"
L23_1.m_Talk_DEU = L24_1
L24_1 = "<color=#ffd34c>Nous l'avons trouvée ! Signes vitaux confirmés !</color>"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SCAVENGER_DIVE50_END@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3100011
L24_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L25_1 = "<color=#ffd34c>함선은 상공에서 대기하세요. 제가 아가씨를 모셔오는 대로 여길 벗어나야 합니다.</color>"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "<color=#ffd34c>艦船は上空で待機してください。私がお嬢様を連れ戻し次第、ここを離れなければなりません。</color>"
L24_1.m_Talk_JPN = L25_1
L25_1 = "<color=#ffd34c>Bridge, stand by in the air. We'll get out of here as soon as I pick up the Lady.</color>"
L24_1.m_Talk_ENG = L25_1
L25_1 = "<color=#ffd34c>艦船在空中預備，等我把小姐帶出來就立刻離開這裡！</color>"
L24_1.m_Talk_TWN = L25_1
L25_1 = "<color=#ffd34c>ห้องควบคุม สแตนด์บายกลางอากาศ เราจะรีบไปจากที่นี่ทันทีที่ฉันรับคุณหนูได้</color>"
L24_1.m_Talk_THA = L25_1
L25_1 = "<color=#ffd34c>Đài Chỉ Huy, hãy chờ liên hệ. Chúng tôi sẽ sớm rời khỏi đây ngay khi tôi đón được Tiểu Thư.</color>"
L24_1.m_Talk_VTN = L25_1
L25_1 = "<color=#ffd34c>舰船在上空待命。我带小姐回来后必须马上离开这里。</color>"
L24_1.m_Talk_SCN = L25_1
L25_1 = "<color=#ffd34c>Brücke, wartet im Luftraum. Sobald ich das Fräulein herbringe, müssen wir weg von hier.</color>"
L24_1.m_Talk_DEU = L25_1
L25_1 = "<color=#ffd34c>Tenez-vous prêt à décoller. Nous quitterons cet endroit dès que serai de retour avec Mme Jia.</color>"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SCAVENGER_DIVE50_END@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3100011
L25_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L26_1 = "<color=#ffd34c>아가씨, 괜찮으신가요?</color>"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "<color=#ffd34c>お嬢様、大丈夫ですか？</color>"
L25_1.m_Talk_JPN = L26_1
L26_1 = "<color=#ffd34c>Miss Jia, are you okay?</color>"
L25_1.m_Talk_ENG = L26_1
L26_1 = "<color=#ffd34c>小姐，您沒事吧？</color>"
L25_1.m_Talk_TWN = L26_1
L26_1 = "<color=#ffd34c>คุณหนู เป็นอะไรรึเปล่าคะ?</color>"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tiểu Thư, cô ổn chứ?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "<color=#ffd34c>小姐，你没事吧？</color>"
L25_1.m_Talk_SCN = L26_1
L26_1 = "<color=#ffd34c>Fräulein! Alles okay?</color>"
L25_1.m_Talk_DEU = L26_1
L26_1 = "<color=#ffd34c>Vous êtes saine et sauve, mademoiselle ?</color>"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
