L29_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L30_1 = "……전 괜찮아요, 이진 언니."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……私は無事です、ホノカさん。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I'm okay, Jin."
L29_1.m_Talk_ENG = L30_1
L30_1 = "……我沒事，李珍姐。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันโอเคค่ะ จิน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi ổn, Jin."
L29_1.m_Talk_VTN = L30_1
L30_1 = "……我没事，李珍姐姐。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Mir geht es gut, Jin."
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Moi, oui. Merci, Jin."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SCAVENGER_DIVE50_END@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3100011
L30_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L31_1 = "연구선은 되찾았으니, 저희 그만 돌아가요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "研究船は取り戻しましたので、戻りましょう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Now that we've retrieved the research ship, we should leave."
L30_1.m_Talk_ENG = L31_1
L31_1 = "既然找到研究船了，那我們回去吧。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ในเมื่อเรากู้ยานวิจัยได้แล้ว เราก็ควรไปจากที่นี่"
L30_1.m_Talk_THA = L31_1
L31_1 = "Giờ chúng ta đã lấy được tàu nghiên cứu. Chúng ta nên đi thôi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "研究船找回来了，我们回去吧。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wir haben das Forschungsschiff wiedererlangt, also gehen wir nun."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Maintenant que nous avons récupéré le vaisseau, nous ferions mieux de partir."
L30_1.m_Talk_FRA = L31_1
