L34_1.m_fWaitTime = 0
L35_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L34_1.m_CharStrID = L35_1
L35_1 = "보고서는 확인했소."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "報告書を確認した。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I read your report."
L34_1.m_Talk_ENG = L35_1
L35_1 = "報告我看完了。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ผมอ่านรายงานของคุณแล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi đã đọc báo cáo của cô."
L34_1.m_Talk_VTN = L35_1
L35_1 = "报告我看了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich habe den Bericht gelesen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "J'ai lu le rapport."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SCAVENGER_DIVE50_END@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3100011
L35_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L35_1.m_CharStrID = L36_1
L36_1 = "아무래도 당신들은 넘버링 라이선스를 가지고 있을 만한 자격이 없는 것 같군."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "どうやらお前たちはナンバリングライセンスを持つ資格がないようだな。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I don't think you deserve your numbered license."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我看你們根本就只是徒有虛名吧？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ผมว่าคุณไม่สมควรได้รับใบอนุญาตทำงานนี้นะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi không nghĩ rằng cô xứng đáng với giấy phép được đánh số của mình đâu."
L35_1.m_Talk_VTN = L36_1
L36_1 = "看来你们根本就没资格拥有执照。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Mir scheint, als seiet ihr nicht zu einer Lizenznummer berechtigt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Laisse-moi te parler franchement : Vous ne méritez pas votre licence numérotée."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "SCAVENGER_DIVE50_END@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3100011
L36_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L36_1.m_CharStrID = L37_1
L37_1 = "텅 빈 연구선을 가져와 놓고 뻔뻔스럽게 보수를 청구하다니 말이야."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "空の研究船を持ってきて、厚かましく報酬を請求するなんて。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You brought an empty research ship and have the audacity to ask for payment?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "帶回一艘空蕩蕩的研究船，還有臉要求支付酬勞？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "คุณเอายานวิจัยเปล่าๆ กลับมา แล้วยังกล้าขอคิดเงินอีกเหรอ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cô đã mang về một con tàu nghiên cứu rỗng và dám yêu cầu thanh toán sao?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "带回一艘空的研究船，居然还好意思厚着脸皮跟我要报酬。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ihr wagt es, ein komplett leeres Forschungsschiff herzubringen und einen Lohn zu verlangen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous rentrez avec un vaisseau vide comme une coquille, et vous avez l'audace de me réclamer un paiement ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SCAVENGER_DIVE50_END@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3100011
L37_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "m_bCharHologramEffect"
L37_1[L38_1] = true
L38_1 = "<color=#ffd34c>스캐빈저에게 나포된 알파트릭스의 연구선을 회수한다.</color>"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "<color=#ffd34c>スカベンジャーに拿捕されたアルファトリックスの研究船を回収する。</color>"
L37_1.m_Talk_JPN = L38_1
L38_1 = "<color=#ffd34c>Retrieve Alphatrix's research ship from the Scavengers.</color>"
L37_1.m_Talk_ENG = L38_1
L38_1 = "<color=#ffd34c>將阿爾法崔克斯集團被清道夫劫走的研究船搶回來。</color>"
L37_1.m_Talk_TWN = L38_1
L38_1 = "<color=#ffd34c>กู้ยานวิจัยของอัลฟาทริกซ์กลับคืนมาจากสคาเวนเจอร์</color>"
L37_1.m_Talk_THA = L38_1
L38_1 = "<color=#ffd34c>Tìm thấy tàu nghiên cứu của Alphatrix từ Scavengers.</color>"
L37_1.m_Talk_VTN = L38_1
L38_1 = "<color=#ffd34c>回收被清道夫劫走的阿尔法崔克斯的研究船。</color>"
L37_1.m_Talk_SCN = L38_1
L38_1 = "<color=#ffd34c>Das Forschungsschiff von Alphatrix bergen, das von den Scavengern gefangen wurde.</color>"
L37_1.m_Talk_DEU = L38_1
L38_1 = "<color=#ffd34c>« Récupérer le vaisseau de recherche d'Alphatrix dérobé par les Scavengers »</color>"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SCAVENGER_DIVE50_END@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3100011
L38_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "당초의 계약 내용은 제대로 이행했습니다만."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "当初の契約内容はしっかり履行したはずです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I believe we've fulfilled our contract."
L38_1.m_Talk_ENG = L39_1
L39_1 = "當時的契約內容是這樣寫的，我應該沒有理解錯誤。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฉันเชื่อว่าเราทำตามที่ระบุในสัญญานะคะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi tin là chúng tôi đã hoàn thành hợp đồng."
L38_1.m_Talk_VTN = L39_1
L39_1 = "这是当初的合同约定，我们已经履行了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Den Vertragsinhalt haben wir korrekt erfüllt, soweit ich weiß."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Nous avons bien rempli notre part du contrat, non ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
