L41_1 = "SCAVENGER_DIVE50_END@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3100011
L40_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L40_1.m_CharStrID = L41_1
L41_1 = "모르는 척 하지 마! 함선에 있던 이볼브 원의 코어를 해적 놈들한테 빼앗겼잖아!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "知らないふりをするな！　艦船のイボルブ・ワンのコアを海賊に奪われただろう！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Don't pretend you don't know! You let the pirates steal the Evolved One's core from the ship!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "少跟我玩文字遊戲！研究船上的Evolved One核心，被那些海盜搶走了不是嗎！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อย่าแกล้งทำเป็นไม่รู้เลย! พวกคุณปล่อยให้โจรสลัดขโมยแกนผู้จุติไปจากยาน!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đừng giả vờ như cô không biết! Cô đã để bọn cướp biển đánh cắp phần lõi của Kẻ Tiến Hóa khỏi con tàu!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "别跟我装傻！舰船上的进化者核心被海盗抢走了不是吗！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Tut nicht so ahnungslos! Ihr habt den Kern von Evolved One, der im Schiff war, an die Piraten verloren!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ne fais pas l'ignorante ! Tu as laissé les pirates partir avec le noyau de l'Evolved One qu'ils ont trouvé dans le vaisseau !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "SCAVENGER_DIVE50_END@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3100011
L41_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L41_1.m_CharStrID = L42_1
L42_1 = "게다가 그 안에 있던 다른 자료들은 전부 어디로 사라진 거지?!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "しかも他の資料は全てどこに消えたんだ！？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "And what about the other data? Where did they go?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "還有那裡面的其他資料呢？都到哪去了？！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แล้วข้อมูลอื่นๆ ล่ะ? หายไปไหน?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Và những dữ liệu khác thì sao? Chúng đã đi đâu mất rồi?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "而且里面的其他资料也全都不见了？！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Und wo sind überhaupt die ganzen Daten hin, die sich darin befunden haben?!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Et les données restantes, alors ? Qu'est-ce que tu en as fait ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "SCAVENGER_DIVE50_END@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3100011
L42_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "m_bCharHologramEffect"
L42_1[L43_1] = true
L43_1 = "먼저 말씀해 주시니 저희도 얘기하기 편하군요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "先におっしゃってくださったので、こちら側も話しやすくなりました。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Thank you for mentioning that before we do."
L42_1.m_Talk_ENG = L43_1
L43_1 = "既然您先提起這件事，那我就開門見山地說了！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ขอบคุณที่พูดเรื่องนี้ขึ้นมาก่อนนะคะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cảm ơn ngài đã đề cập đến điều đó trước khi chúng tôi nói."
L42_1.m_Talk_VTN = L43_1
L43_1 = "既然您先开口了，那我们就不客气了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Schön, dass Sie das zuerst ansprechen. Das macht es einfacher."
L42_1.m_Talk_DEU = L43_1
L43_1 = "J'y venais, justement. Merci d'avoir abordé le sujet avant moi."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCAVENGER_DIVE50_END@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3100011
L43_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_IDLE"
L43_1.m_Face = L44_1
L44_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "그 안에 있는 연구 자료들 중에는 불법적인 종류도 상당히 섞여 있지 않았을까요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "その中にある研究資料の中には、違法に当たる内容もかなり混ざっていたのではないでしょうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "What if a majority of the lost data was illegal?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "那些研究資料裡，其中也有許多不法的內容吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แล้วถ้าเกิดข้อมูลที่หายไปส่วนใหญ่เป็นข้อมูลผิดกฎหมายล่ะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Điều gì sẽ xảy ra nếu phần lớn dữ liệu bị mất là bất hợp pháp?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "那里面的研究资料中，掺杂着很多非法资料不是吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Unter den Forschungsdaten darin waren ziemlich viele illegale Arten dabei, nicht wahr?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Que se passerait-il si la majorité de ces données était illégale ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SCAVENGER_DIVE50_END@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3100011
L44_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "가령, 전량 압류되어야 했을 리플레이서 신디케이트의 연구 자료들이라거나 말이죠."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "たとえば、全て管理局に差し押さえられるはずのリプレイサー・シンジケートの研究資料など。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Data about the Replacer Syndicate, which should have been turned in to the Administration, for example."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我猜，那些是原本應該要被扣押的，克隆集團企業聯合組織研究資料吧？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เช่นข้อมูลเกี่ยวกับองค์การบริหารโลก ซึ่งสมควรจะต้องส่งให้องค์การบริหารโลก"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ví dụ: dữ liệu về Replacer Syndicate, đáng lẽ ra phải được nộp cho Cục Quản Lý. "
L44_1.m_Talk_VTN = L45_1
L45_1 = "比方说，本应该扣查转交给管理局的克隆集团研究数据。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wie etwa Daten zum Replacer-Syndikat, die allesamt konfisziert hätten werden müssen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Si elles étaient liées au Syndicat des substituts, par exemple... ? Ne devraient-elle pas être remises à l'Administration ?"
L44_1.m_Talk_FRA = L45_1
