L47_1.m_fWaitTime = 0
L48_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L47_1.m_CharStrID = L48_1
L48_1 = "자료는 어쩔 셈이지?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "資料はどうするつもりだ？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What are you going to do with that data?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "妳想拿那些資料做什麼？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "พวกคุณจะทำอะไรกับข้อมูลนั่น?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Cô định làm gì với dữ liệu đó?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "你想拿那些资料做什么！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Was habt ihr mit den Daten vor?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Et qu'est-ce que vous comptez faire de ces données, exactement ?"
L47_1.m_Talk_FRA = L48_1
