L49_1 = "SCAVENGER_DIVE50_END@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3100011
L48_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L48_1.m_CharStrID = L49_1
L49_1 = "경고해 두는데, 우리 그룹 연구 자료에 손가락 하나 댔다간 평생을 소송전으로 보내야 할 거야. "
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "警告しておくが、我がグループの研究資料に指一本でも触れたら、一生訴訟戦に時間を費やされることになる。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I warn you: you'd better not touch any of them, or you'll spend the rest of your life in court. "
L48_1.m_Talk_ENG = L49_1
L49_1 = "我可是警告妳，妳要是敢碰我們集團的研究資料，我一定會告死妳！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ขอเตือนไว้ก่อนนะ อย่าคิดจะแตะต้องมันเด็ดขาด ไม่งั้นได้ขึ้นศาลไปอีกตลอดชีวิตแน่"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi cảnh cáo cô: đừng có chạm vào bất kỳ thứ gì trong số chúng, nếu không cô sẽ dành hết phần đời còn lại của mình để hầu tòa đấy."
L48_1.m_Talk_VTN = L49_1
L49_1 = "我警告你，你们要是敢碰我们集团的研究资料，就等着一辈子官司缠身吧。 "
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich warne euch. Wenn ihr die Forschungsdaten unseres Konzerns auch nur anrührt, werdet ihr den Rest eures Lebens vor Gericht verbringen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je te préviens : Vous n'avez pas intérêt à les utiliser, ou vous passerez le reste de vos jours au tribunal. "
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
