L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L50_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "m_bCharHologramEffect"
L49_1[L50_1] = true
L50_1 = "물론 저희가 회수한 분실물들은 곧 부회장님 집무실로 배송될 겁니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "もちろん弊社が回収した紛失物は、間もなく副会長の執務室に配送される予定です。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "All the lost assets we retrieved will be sent to your office, Mr. Vice Chairman."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我們找回來的遺失物，很快就會送到副會長的辦公室。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เราจะส่งทรัพย์สินทั้งหมดที่เรากู้มาได้ไปที่ออฟฟิศของคุณค่ะ ท่านรองประธาน"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tất cả những tài sản bị mất mà chúng tôi lấy được sẽ được gửi đến văn phòng của ông, thưa Phó Chủ Tịch."
L49_1.m_Talk_VTN = L50_1
L50_1 = "当然不会，我们回收的失物很快就会寄到副会长您的办公室。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Selbstverständlich werden die Fundsachen, die wir erlangt haben, bald in Ihr Büro geliefert werden, Vizepräsident."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Tous les éléments que nous parviendrons à récupérer vous seront restitués à votre bureau, M. le Vice-président."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
