L51_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "애초에 멘탈 프린팅을 어설프게 흉내내려 한 실패일지에는 관심 없으니까요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "そもそもメンタル・プリンティングを中途半端に真似した失敗記録には興味ありませんので。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "We're not interested in failed research about wasted attempts at imitating Mental Printing."
L50_1.m_Talk_ENG = L51_1
L51_1 = "反正我打從一開始，就對想要草率模仿智力複印的失敗日誌沒興趣。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เราไม่สนใจเรื่องงานวิจัยที่ล้มเหลวเกี่ยวกับความพยายามอันสูญเปล่าในการเลียนแบบการพิมพ์จิต"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng tôi không quan tâm đến nghiên cứu thất bại để bắt chước Mental Printing một cách lãng phí."
L50_1.m_Talk_VTN = L51_1
L51_1 = "因为我们一开始就对蹩脚地模仿精神拓印技术的失败日志不感兴趣。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Uns sind nämlich die gescheiterten Versuche des Mentalbedrucks eher egal."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Des recherches inutiles à propos d'expériences ratées visant à imiter l'impression mémorielle ? Très peu pour nous."
L50_1.m_Talk_FRA = L51_1
