L4_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L3_1.m_CharStrID = L4_1
L4_1 = "아니, 그보다 어떻게 멘탈 프린팅 기술에 대해 알고 있는 건가?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "いや、それよりどうしてメンタル・プリンティング技術について知っているんだ？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Wait, how do you know about Mental Printing?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "妳怎麼會知道智力複印技術？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เดี๋ยวนะ นี่คุณรู้เรื่องการพิมพ์จิตได้ยังไง"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chờ đã, sao cô biết về Mental Printing?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "不对，你是怎么知道精神拓印技术的？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Nein, Moment, woher wisst ihr überhaupt über den Mentalbedruck Bescheid?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Comment as-tu entendu parler de l'impression mémorielle ?"
L3_1.m_Talk_FRA = L4_1
