L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "m_bCharHologramEffect"
L4_1[L5_1] = true
L5_1 = "그거야말로 그쪽이 신경 쓸 일이 아니지 않나요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それこそ御社に話す必要ない案件だと思いますが。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "That's none of your business, is it?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我怎麼知道的不關您的事吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "นั่นไม่ใช่เรื่องของคุณไม่ใช่เหรอคะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đó không phải việc của cô, biết chưa?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "这个就不是您该操心的事了呢。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Das geht Sie nichts an, meinen Sie nicht auch?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Cela ne vous regarde pas."
L4_1.m_Talk_FRA = L5_1
