L6_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "조만간 저희 사장님께서 연락드릴 예정이니 추가수당에 대해서나 생각해 두시죠."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "近いうちに弊社の社長から連絡する予定ですので、追加手当について事前に用意していただければと思います。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "My CEO will contact you soon. You'll have enough time to calculate our extra payment until then."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我們老闆稍後會和您聯絡，應該是要跟您談額外的費用。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "CEO ของฉันจะติดต่อคุณไปในเร็วๆ นี้ คุณยังมีเวลามากพอให้คำนวณค่าตอบแทนเพิ่มเติมของเราจนกว่าจะถึงตอนนั้น"
L5_1.m_Talk_THA = L6_1
L6_1 = "CEO của tôi sẽ liên hệ với ngài sớm. Ngài sẽ có đủ thời gian để tính toán khoản tiền bổ sung cho chúng tôi cho đến lúc đó."
L5_1.m_Talk_VTN = L6_1
L6_1 = "不久后我们老板就会联系您，您还是先想想该给多少额外报酬吧。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Bald wird Sie unser Boss kontaktieren, also überlegen Sie sich lieber die Höhe unseres Extralohns."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Notre président vous contactera bientôt. D'ici-là, vous aurez largement le temps de calculer le montant de notre prime."
L5_1.m_Talk_FRA = L6_1
