L11_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "흐음, 나한테 감사 인사를 하러 왔다고?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ふむ、私にお礼を言いに来たと？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Hm, you came to thank me?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "呵～妳是來謝我的嗎？ "
L10_1.m_Talk_TWN = L11_1
L11_1 = "หืม มาเพื่อขอบคุณผมเหรอ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Hử, cô đến để cảm ơn tôi ư?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "嗯，你是来感谢我的？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Oho, ihr seid hier, um mir zu danken?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Oh, tu es venue me remercier ?"
L10_1.m_Talk_FRA = L11_1
