L12_1 = "SCAVENGER_DIVE50_END@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3100011
L11_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_LAUGH"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "네, 이번 작전 때 사장님의 친구 분을 통해서 선물을 받았거든요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はい、今回の作戦で社長の友人の方からプレゼントをいただいたのです。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Yes. Your friend gave us a valuable gift during the last operation."
L11_1.m_Talk_ENG = L12_1
L12_1 = "是的，這次作戰時，老闆的朋友有送我一個禮物。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ใช่ค่ะ เพื่อนของคุณมอบของขวัญล้ำค่าให้ฉันระหว่างปฏิบัติการครั้งก่อน"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đúng. Bạn của ngài đã tặng chúng tôi một món quà giá trị trong lần tác chiến vừa qua."
L11_1.m_Talk_VTN = L12_1
L12_1 = "是，这次作战时，我通过老板的朋友收到了礼物。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Genau. Bei der letzten Operation haben wir ein Geschenk über einen Freund von Ihnen erhalten."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Oui. Votre amie m'a fait un cadeau lors de notre dernière opération."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SCAVENGER_DIVE50_END@162#Talk"
