L12_1.m_Pos = "C"
L13_1 = "덕분에 많은 도움이 됐어요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "おかげで本当に助かりました。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "It helped us tremendously."
L12_1.m_Talk_ENG = L13_1
L13_1 = "這個禮物幫上許多忙呢！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มันช่วยเราไว้ได้มากเลยค่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nó đã giúp chúng tôi rất nhiều."
L12_1.m_Talk_VTN = L13_1
L13_1 = "那个礼物帮了我很大的忙。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Das hat uns ungemein geholfen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Un objet qui m'a été très utile."
L12_1.m_Talk_FRA = L13_1
