L13_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "이거, 별거 아니지만 답례로 받아주시겠어요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "こちら、つまらないものですが受け取っていただけると幸いです。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "This is nothing, but I'd like to give it to you."
L13_1.m_Talk_ENG = L14_1
L14_1 = "這是一點點小心意，送給老闆作為謝禮。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นี่เป็นของเล็กๆ น้อยๆ นะคะ แต่ฉันอยากให้คุณไว้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cái này chẳng là gì, nhưng tôi muốn tặng nó cho ngài."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这是我的一点心意，不成敬意，请您收下。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Das hier. Es ist nichts besonderes. Aber nehmen Sie es bitte an."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ce n'est pas grand chose, mais j'aimerais vous donner ceci pour vous remercier."
L13_1.m_Talk_FRA = L14_1
