L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "오오옷! 이건 알파트릭스표 최고급 알칼라인 연료 전지!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "おおおっ！　これはアルファトリックス製最高級アルカリ燃料電池！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Ooooh! Alphatrix's finest alkaline fuel batteries!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "哇哇哇！這是阿爾法崔克斯牌最高級的鹼性燃料電池欸！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "โอ้ววว! แบตเตอรี่เชื้อเพลิงอัลคาไลน์ชั้นดีที่สุดของอัลฟาทริกซ์!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ooooh! Pin nhiên liệu alkaline tốt nhất của Alphatrix!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "噢噢噢！阿尔法崔克斯的顶级碱性燃料电池！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Oooh! Das sind doch die besten alkalischen Brennstoffbatterien von Alphatrix!"
