L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "자네, 물건 보는 안목이 좀 있구만!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "君、物を見る目があるな！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "You've got good taste!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "想不到妳滿會挑禮物的嘛！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "คุณนี่รสนิยมดีนะครับ!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cô có gu hay đấy!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "沈佳小姐很识货啊！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Du hast einen exzellenten Geschmack!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Tu sais faire plaisir à tes amis, Jia !"
