L16_1.m_Face = L17_1
L16_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "후훗. 좋아해 주셔서 저도 기뻐요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "フフッ、喜んでもらえて私も嬉しいです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Heh heh. I'm glad you like them."
L16_1.m_Talk_ENG = L17_1
L17_1 = "呵呵～我也很開心你喜歡。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แหะๆ ดีใจนะคะที่คุณชอบ"
L16_1.m_Talk_THA = L17_1
L17_1 = "He he, tôi rất vui vì ngài thích chúng."
L16_1.m_Talk_VTN = L17_1
L17_1 = "呵呵，看到你喜欢，我也很开心。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hehe. Es freut mich, dass es Ihnen gefällt."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Hi hi. Je suis heureuse que ça vous plaise."
L16_1.m_Talk_FRA = L17_1
