L18_1 = "UNIT_IDLE"
L17_1.m_Face = L18_1
L17_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "그리고 이건 파견을 나간 샤오린 씨를 위해 준비한 선물인데, 대신 전해 주시겠어요?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "そして、これはシャオリンさんのために用意したプレゼントなのですが、代わりに渡していただけませんか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "And this is for Xiao Lin. Could you give it to her when she returns?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "另外這個是要送給曉琳的禮物，她現在正在派遣中吧？再麻煩老闆幫我轉交給她。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "และนี่สำหรับเสี่ยวหลิน ถ้าเธอกลับมาเมื่อไหร่ คุณช่วยเอาให้เธอได้มั้ยคะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Và cái này là cho Xiao Lin. Ngài có thể đưa nó cho cô ấy khi cô ấy trở về không?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "还有，我给这次出任务的小琳也准备了礼物，你能替我转交给她吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Und das hier ist ein Geschenk für Xiao Lin, die sich im Außendienst befindet. Geben Sie Ihr das bitte an meiner Stelle?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh, et vous voulez bien donner ceci à Xiao Lin quand vous la verrez ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
