L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "……건강 야채 한 박스와 수면 안대?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "……超濃縮健康野菜ジュースと就寝用アイマスク？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "A box of healthy vegetables and a sleep mask?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "……健康養身蔬菜一箱和眼罩？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เซ็ตผักเพื่อสุขภาพกับหน้ากากปิดตาตอนนอนเหรอ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Một hộp rau lành mạnh và mặt nạ ngủ ư?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "……一箱子健康蔬菜和睡眠眼罩？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Eine Kiste voller gesundem Gemüse und eine Schlafmaske?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Un sac de légumes et un bandeau pour les yeux... ?"
