L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "샤오린 양이 이런 걸 좋아했던가?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "シャオリンはこういう物が好きだったかな？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Did she like these sorts of things?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "曉琳喜歡這種東西喔？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เสี่ยวหลินชอบของพวกนี้เหรอเนี่ย?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Xiao Lin thích mấy thứ này sao?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "小琳喜欢这些东西吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Seit wann mag Xiao Lin solche Sachen?"
L21_1.m_Talk_DEU = L22_1
