L26_1 = "SYSOP_NPC_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "타이탄의 설계자를 찾는다고?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "タイタンの設計者を探していると？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "You're looking for the designer of the Titan?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "妳要找泰坦的設計人？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เธออยากพบผู้ที่ออกแบบไททันงั้นเหรอ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cô đang tìm nhà thiết kế của Titan ư?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "你要找泰坦的设计者？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ihr sucht nach dem Designer von Titan?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Tu cherches le créateur du Titan ?"
L25_1.m_Talk_FRA = L26_1
