L27_1 = "SCAVENGER_DIVE50_END@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3100011
L26_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "COLLECTOR_NPC_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "그래, 타이탄의 골조 설계와 동작 이론에 대한 정보가 필요해."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そう、タイタンの骨組み設計と動作理論に関する情報が必要だ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Yes. I need information about the Titan's framework and theory of operation."
L26_1.m_Talk_ENG = L27_1
L27_1 = "對，我需要有關泰坦結構和動作理論的資料。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ใช่ ฉันต้องการข้อมูลเกี่ยวกับโครงประกอบและทฤษฎีปฏิบัติการของไททัน"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đúng vậy. Tôi cần thông tin về cơ cấu và lý thuyết hoạt động của Titan."
L26_1.m_Talk_VTN = L27_1
L27_1 = "是，我需要关于泰坦框架设计和运转理论的信息。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Genau. Ja. Ich brauche Informationen über das Gerüst und die Betriebstheorie von Titan."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Oui. J'ai besoin d'en apprendre plus sur son architecture et sur ses principes de fonctionnement."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "SCAVENGER_DIVE50_END@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3100011
L27_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "COLLECTOR_NPC_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "그런 거대한 로봇을 움직이는 건 내 개조만으론 어려운 일이거든."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あんな巨大なロボットを動かすのは、私の改造技術だけじゃ難しくてね。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I can modify machines, but I don't know how to move a big robot like this."
L27_1.m_Talk_ENG = L28_1
L28_1 = "光憑我的改造，是不可能讓那麼巨大的機器人動起來的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันทำได้แค่ดัดแปลงเครื่องจักร แต่ฉันไม่รู้วิธีทำให้หุ่นยนต์ที่ใหญ่ขนาดนั้นเคลื่อนไหว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi có thể sửa đổi máy móc, nhưng tôi không biết làm thế nào để di chuyển một con robot lớn như thế này."
L27_1.m_Talk_VTN = L28_1
L28_1 = "因为仅凭我的改造，很难操控那么庞大的机器人。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Um so einen gigantischen Roboter zu bewegen, braucht man mehr als nur meine Modifikationen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je peux modifier les machines, mais je suis incapable de déplacer un robot aussi colossal."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
