L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3100011
L29_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "COLLECTOR_NPC_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "너라면 그녀가 어디 있는지 알고 있겠지. "
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "お前なら彼女がどこにいるかわかるだろ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "You know where she is, don't you? "
L29_1.m_Talk_ENG = L30_1
L30_1 = "你應該知道她在哪裡吧？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "รู้ว่าหล่อนอยู่ที่ไหนใช่มั้ย?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Biết cô ấy ở đâu không?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你应该知道她在哪儿吧。 "
L29_1.m_Talk_SCN = L30_1
L30_1 = "Du würdest wissen, wo sie ist."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Tu sais où elle se trouve, n'est-ce pas ? "
L29_1.m_Talk_FRA = L30_1
