L31_1 = "SCAVENGER_DIVE50_END@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3100011
L30_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_IDLE"
L30_1.m_Face = L31_1
L31_1 = "COLLECTOR_NPC_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "평의회의 이름으로 평소에도 온갖 정보를 수집하고 다니고 있잖아."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "評議会の名前を使って、普段からあらゆる情報を収集しているじゃないか。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You're collecting all kinds of information in the name of the Council."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你不是整天打著評議會的名義，到處收集資料嗎！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เธอรวบรวมข้อมูลทุกรูปแบบในนามของสภา"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đằng đó đang thu thập tất cả các loại thông tin dưới danh nghĩa của Hội Đồng."
L30_1.m_Talk_VTN = L31_1
L31_1 = "你平时不都以评议会的名义收集各种信息吗。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Du sammelst schließlich alle möglichen Infos im Namen des Parlaments."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je sais bien que tu collectes toutes sortes d'information au nom du Conseil."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
