L33_1 = "SCAVENGER_DIVE50_END@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3100011
L32_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "SYSOP_NPC_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "의외로군. 그쪽이 기계도 아닌 사람에게 관심을 가질 줄은 몰랐어."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "意外だな。機械でもない人間に興味が湧いたとは。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "This is rather unexpected. I'd never thought you'd take an interest in anything that isn't a machine."
L32_1.m_Talk_ENG = L33_1
L33_1 = "真是意外，妳竟然會對人有興趣，我還以為妳眼裡只有機械。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คาดไม่ถึงเลยนะเนี่ย ฉันไม่เคยคิดว่าเธอจะสนใจอะไรที่ไม่ใช่เครื่องจักร"
L32_1.m_Talk_THA = L33_1
L33_1 = "Điều này khá là bất ngờ. Tôi chưa bao giờ nghĩ rằng cô sẽ quan tâm đến bất cứ thứ gì ngoài máy móc."
L32_1.m_Talk_VTN = L33_1
L33_1 = "真意外啊，没想到你还会对机械以外的人感兴趣。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie unerwartet. Ich hätte nicht gedacht, dass du Interesse an einem Menschen statt nur an Maschinen zeigst."
L32_1.m_Talk_DEU = L33_1
L33_1 = "C'est inattendu. Tu t'intéresses à autre chose qu'aux machines, maintenant ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SCAVENGER_DIVE50_END@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3100011
L33_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "SYSOP_NPC_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "하지만 엠버 박사라……."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "しかしアンバー博士か……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But Doctor Ember, huh?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "不過琥珀博士她……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ด็อกเตอร์เอมเบอร์เนี่ยนะ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng Tiến Sĩ Ember, phải không?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "不过安珀博士……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber Ember ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais le professeur Ember..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SCAVENGER_DIVE50_END@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3100011
L34_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "SYSOP_NPC_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "그녀라면 퓨처 앳 워에서 제명된 이후 불법 반출된 아티팩트를 수소문했다는 기록이 있어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "彼女ならフューチャーアットウォーから除名された後、違法搬出されたアーティファクトを探し回っていたという記録がある。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "There's a record of her looking for some illegally transferred Artifacts after she was expelled from Future-at-War."
L34_1.m_Talk_ENG = L35_1
L35_1 = "記錄顯示，自從她從天啟兵器中被除名後，就在打聽非法輸出的神器。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "มีบันทึกที่ระบุว่าหล่อนกำลังมองหาอาร์ติแฟ็กต์ที่ขนย้ายมาอย่างผิดกฎหมาย หลังจากที่ถูกปลดออกจากฟิวเจอร์-แอท-วอร์"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có một hồ sơ về việc cô ấy đang tìm kiếm một số Thần Khí được chuyển giao bất hợp pháp sau khi cô ấy bị loại khỏi Chiến Tranh Tương Lai."
L34_1.m_Talk_VTN = L35_1
L35_1 = "有消息称，自从她被天启兵器除名后，就一直在打听非法运输的人造神器。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Zu ihr gibt es einen Eintrag, der besagt, dass sie nach ihrer Verbannung aus Future-at-War lauter Artefakte aufspüren wollte, die illegal transferiert worden sind."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Il y a une archive sur laquelle on peut la voir chercher des artefacts illégalement transférés, au lendemain de sa destitution à Future-at-War."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SCAVENGER_DIVE50_END@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3100011
L35_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "SYSOP_NPC_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "그러다 마지막엔 소형선을 타고 혼자 이면세계로 떠난 뒤……"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "そして最後は小型船に乗って、一人で裏世界に旅立った後……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "In the end, she took a small ship and left for the Counterside by herself."
L35_1.m_Talk_ENG = L36_1
L36_1 = "最後的記錄，是她搭著一艘小船獨自前往異界……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "สุดท้ายหล่อนก็เอายานลำเล็กไป แล้วก็ไปที่เคาน์เตอร์ไซด์คนเดียว"
L35_1.m_Talk_THA = L36_1
L36_1 = "Cuối cùng, cô ấy đã lấy một con tàu nhỏ và tự mình bỏ đi đến Counterside."
L35_1.m_Talk_VTN = L36_1
L36_1 = "最后的记录，显示她搭载着一艘小型舰船，独自前往了异界……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Am Ende stieg sie auf ein kleines Schiff und ist allein gen Counterside aufgebrochen ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Elle a été vue pour la dernière fois à bord d'un petit vaisseau en route pour le Contremonde."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
