L37_1 = "SYSOP_NPC_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "행방이 묘연해졌지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "行方不明になった。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "She hasn't been seen since then."
L36_1.m_Talk_ENG = L37_1
L37_1 = "之後她便行蹤不明。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่เคยมีใครเห็นหล่อนอีกหลังจากนั้น"
L36_1.m_Talk_THA = L37_1
L37_1 = "Từ đó chẳng ai thấy cô ấy cả."
L36_1.m_Talk_VTN = L37_1
L37_1 = "之后就彻底失去了踪迹。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Seitdem hörte man nichts mehr von ihr."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Depuis, plus de nouvelles."
L36_1.m_Talk_FRA = L37_1
