L38_1 = "SCAVENGER_DIVE50_END@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3100011
L37_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "SYSOP_NPC_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "구조 신호를 보낸 기록은 있는데, 결국 아무것도 발견되지 않았어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "救助信号を送った記録はあるが、結局何も見つからなかった。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "There's a record of her sending rescue signals, but she was never found."
L37_1.m_Talk_ENG = L38_1
L38_1 = "雖然有發出求救訊號的記錄，結果卻沒有任何的發現。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "มีบันทึกว่าหล่อนส่งสัญญาณขอความช่วยเหลือกลับมา แต่ไม่มีใครพบตัว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Từng có rất nhiều lần hồ sơ ghi lại việc cô ấy gửi tin hiệu cầu cứu, nhưng chẳng có ai từng tìm thấy cô ấy cả."
L37_1.m_Talk_VTN = L38_1
L38_1 = "有过发送求救信号的记录，但最后什么都没发现。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Es gibt Aufzeichnungen darüber, dass sie Notsignale ausgesandt hatte, doch man hat sie nie mehr gefunden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "On a bien enregistré des signaux de détresse venant de sa part, mais elle n'a jamais été retrouvée."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
