L40_1 = "COLLECTOR_NPC_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "술집 주정뱅이도 해 줄 것 같은 아무 영양가 없는 이야기잖아?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "酒場で飲みつぶれている奴からも聞けそうな、何の役にも立たない話だな？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I could have just talked to some drunk at a bar and heard the same story."
L39_1.m_Talk_ENG = L40_1
L40_1 = "這些內容我隨便找個小酒館抓個醉漢來問，他都會告訴我吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คนเมาที่บาร์ก็เล่าแบบเดียวกันนี้ได้"
L39_1.m_Talk_THA = L40_1
L40_1 = "Một tên say sỉn ở quán bar cũng kể được những chuyện tương tự."
L39_1.m_Talk_VTN = L40_1
L40_1 = "都是一些没什么用的内容啊，连酒馆的酒鬼也能讲出来吧。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Das ist bloßer Tratsch, den ich von jedem Trunkenbold in der Schenke hätte hören können."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Même l'alcoolique de la taverne du coin aurait pu m'en dire plus."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
