L41_1 = "COLLECTOR_NPC_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "됐어. 나 혼자서 알아 봐야겠네."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "もういい。自分で調べる。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Forget it. I'm going to find her on my own."
L40_1.m_Talk_ENG = L41_1
L41_1 = "真是沒用！我看我還是靠自己打聽吧！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ช่างมันเถอะ ฉันจะตามหาเธอด้วยตัวเอง"
L40_1.m_Talk_THA = L41_1
L41_1 = "Quên đi. Tôi sẽ tự tìm cô ấy."
L40_1.m_Talk_VTN = L41_1
L41_1 = "算了，我还是自己去打听吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Vergiss es. Ich erkundige mich anderweitig."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Bah, laisse tomber. Je vais aller la chercher moi-même."
L40_1.m_Talk_FRA = L41_1
