L43_1 = "SCAVENGER_DIVE50_END@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3100011
L42_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "SYSOP_NPC_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "흐흠. 참을성 없는 건 여전하군. 조금만 더 들어 봐."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ふっ。せっかちなのは相変わらずだな。もう少し人の話を聞け。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Hah hah. You're as impatient as ever. I'm not finished."
L42_1.m_Talk_ENG = L43_1
L43_1 = "呵～妳還是一樣沒耐心呢！我話又還沒說完。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฮ่าๆ เธอนี่ยังใจร้อนเหมือนเดิมนะ ฉันยังเล่าไม่จบเลย"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ha ha. Cô vẫn chẳng kiên nhẫn gì hết. Tôi chưa nói xong."
L42_1.m_Talk_VTN = L43_1
L43_1 = "唉，你还是这么没耐心呢。你再听我接着说啊。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hmpf. Du bist immer noch ungeduldig wie immer. Hör mal weiter zu."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ha ha, quelle impatience ! Je n'ai pas fini, tu sais ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCAVENGER_DIVE50_END@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3100011
L43_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "SYSOP_NPC_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "신원으로 확인할 수 있는 정보는 이게 전부지만, 여기서부턴 논리적으로 접근해 보자고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "確認できる情報はこれがすべてだが、ここからは論理的に考えてみよう。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I told you everything I could learn based on her identity, but let's use logic from now on."
L43_1.m_Talk_ENG = L44_1
L44_1 = "以我的身份能打聽到的就是這些，但接下來才是精彩的地方，我要開始推理囉！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันบอกทุกอย่างที่รู้ โดยดูจากตัวตนของหล่อน แต่จากนี้เรามาคุยกันด้วยตรรกะนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi đã nói với cô mọi thứ tôi có thể tìm hiểu dược dựa trên danh tính của cô ấy, nhưng từ bây giờ, hãy logic một chút đi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "身份上可以确认的信息就只有这些，不过这之后我们可以用逻辑去分析。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Das waren alle Infos, die man durch ihre Personalien findet. Aber lass uns ab jetzt logisch denken."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Jusque là, je n'ai fait qu'énoncer les faits. Et maintenant, si on essayait de raisonner ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SCAVENGER_DIVE50_END@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3100011
L44_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "SYSOP_NPC_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "일자리를 잃은 과학자의 발자취가 왜 하필 이면세계에서 끊겼는지 말이야."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "職を失った科学者の足跡が、なぜよりによって裏世界で途絶えたのか。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Why would an unemployed scientist go to the Counterside of all places?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "妳想想，一個失業的科學家，為何足跡偏偏停留在異界呢？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ทำไมนักวิทยาศาสตร์ที่ถูกเลิกจ้างถึงเลือกที่จะไปที่เคาน์เตอร์ไซด์?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tại sao một nhà khoa học thất nghiệp lại chọn Counterside bên cạnh tất cả những địa điểm khác chứ?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "为什么一个失去工作的科学家会满异界地乱逛呢？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Warum sind die Spuren eines arbeitslosen Forschers ausgerechnet in Counterside geendet?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "D'après toi, que pourrait bien aller faire une scientifique au chômage dans le Contremonde ?"
L44_1.m_Talk_FRA = L45_1
