L47_1 = "SCAVENGER_DIVE50_END@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3100011
L46_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "COLLECTOR_NPC_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "글쎄. 직장을 잃은 충격으로 어디 조용한 곳에서 혼자 죽으려 했나?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "さあな。仕事を失った衝撃で、どっか静かなところで一人で死のうとでもしたのか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I don't know. Maybe she was so upset about losing her job that she decided to kill herself somewhere quiet."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我怎麼知道！可能是失業的打擊太大，她想找個沒人的地方結束生命吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ไม่รู้สิ อาจจะโมโหที่เสียงานจนตัดสินใจหาที่ฆ่าตัวตายเงียบๆ ก็ได้"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ai biết. Có lẽ cô ấy quá buồn vì mất việc nên đã quyết định tự sát ở một nơi nào đó yên tĩnh chăng."
L46_1.m_Talk_VTN = L47_1
L47_1 = "这个嘛，难道是因为失业受打击，想去一个安静的地方自杀？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Keine Ahnung. Wollte sie ihr Leben ein Ende setzen, weil sie ihren Jobverlust nicht verkraftet hat?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "J'en sais rien, moi. Elle était peut-être si déprimée d'avoir perdu son boulot qu'elle a voulu aller en finir à l'abri des regards ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
