L48_1 = {}
L49_1 = "SCAVENGER_DIVE50_END@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3100011
L48_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "SYSOP_NPC_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "당연한 얘기지만, 이면세계엔 블랙 네트워크에도 없는 것들이 아주 많지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "当たり前の話だが、裏世界にはブラックネットワークじゃ入手できないものがたくさん存在する。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "This is obvious, but the Counterside is filled with things that you can't find even on the Dark Network."
L48_1.m_Talk_ENG = L49_1
L49_1 = "妳說的也有道理，但異界可是有許多連黑色網絡也沒有的東西。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เคาน์เตอร์ไซด์เต็มไปด้วยสรรพสิ่งที่เราจะไม่มีวันหาพบ แม้แต่ในดาร์กเน็ตเวิร์ก"
L48_1.m_Talk_THA = L49_1
L49_1 = "Hiển nhiên rồi, nhưng Counterside chứa đầy những thứ mà cô không thể tìm thấy ngay cả trên Mạng Đen."
L48_1.m_Talk_VTN = L49_1
L49_1 = "……算了，我继续说吧，你也知道异界有很多黑色网络中也没有的东西。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wie jeder weiß, gibt es viele Dinge in Counterside, die man nicht mal im Schattennetz findet."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Le Contremonde est truffé de mystères auxquels même le dark net ne peut pas répondre. Jusqu'ici je ne t'apprends rien, n'est-ce pas ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SCAVENGER_DIVE50_END@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3100011
L49_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "SYSOP_NPC_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "엠버 박사가 만든 타이탄도 이면세계에서 발견된 메인 프레임으로 완성된 결과물이고."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "アンバー博士が作ったタイタンも、裏世界で発見されたメインフレームで完成したものだ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Her Titan's main frame was also discovered on the Counterside."
L49_1.m_Talk_ENG = L50_1
L50_1 = "琥珀博士創造的泰坦，也是利用在異界發現的大型主機製造而成的。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "โครบประกอบหลักของไททันของหล่อนก็ถูกค้นพบในเคาน์เตอร์ไซด์"
L49_1.m_Talk_THA = L50_1
L50_1 = "Khung chính của Titan cũng được khám phá ở Counterside."
L49_1.m_Talk_VTN = L50_1
L50_1 = "安珀博士制造的泰坦也是在异界发现的主框架基础上完成的。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Auch der Titan, den Dr. Ember erschaffen hat, basiert auf einem Hauptgerüst, das sie in Counterside entdeckt hat."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Titan, la création du professeur Ember, a été créé à partir d'une structure découverte là-bas."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SCAVENGER_DIVE50_END@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3100011
L50_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "SYSOP_NPC_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "박사는 다시 한 번 타이탄 같은…… 어쩌면 그보다 더 뛰어난 소재를 찾고 싶었을지도 몰라."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "博士はもう一度タイタンのような……もしかしたらそれよりもっと優れた素材を見つけたかったのかもしれない。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Maybe Doctor Ember wanted to find another Titan... or something better."
L50_1.m_Talk_ENG = L51_1
L51_1 = "所以我猜，琥珀博士很可能是想再創造一個像泰坦一樣，不……甚至是比泰坦更厲害的機械，才會到異界去找材料。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ด็อกเตอร์เอมเบอร์อาจจะอยากหาไททันตัวอื่น... หรืออะไรที่ดีกว่านั้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Có lẽ Tiến Sĩ Ember đã muốn tìm một Titan khác... hay cái gì đó tốt hơn."
L50_1.m_Talk_VTN = L51_1
L51_1 = "博士说不定是想再次找到跟泰坦一样……或者比泰坦更优秀的材料。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Vielleicht wollte sie ein Material finden, dass dem für Titan gleicht ... oder es sogar übertrifft."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Qui sait, peut-être qu'elle était à la recherche d'un autre Titan ? Ou même de quelque chose d'encore plus puissant ?"
L50_1.m_Talk_FRA = L51_1
