L2_1 = "SCAVENGER_DIVE50_END@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3100011
L1_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_SERIOUS"
L2_1 = "COLLECTOR_NPC_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "그렇다고 일반인이 혼자 이면세계를 탐색한다는 건 그냥 죽겠다는 소리 아닌가?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だからといって、一般人が一人で裏世界を探索するなんて自殺行為だろう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "But you have to be suicidal to explore the Counterside by yourself when you're just an ordinary person."
L1_1.m_Talk_ENG = L2_1
L2_1 = "意思就是，她一個平凡人到異界找材料，然後她就死掉了？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่การจะสำรวจเคาน์เตอร์ไซด์ด้วยตัวเอง\nทั้งที่เป็นคนธรรมดาได้นั้นต้องเตรียมตัวตายไว้ด้วย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nhưng tự mình khám phá Counterside khi chỉ là một người bình thường chẳng khác nào tự sát."
L1_1.m_Talk_VTN = L2_1
L2_1 = "可是普通人孤身一人探索异界不就是去送死吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber wenn ein gewöhnlicher Mensch sich allein in Counterside umsehen will, ist das reiner Selbstmord."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais pourquoi partir en expédition seule dans le Contremonde ? Pour une simple humaine, c'est du suicide !"
L1_1.m_Talk_FRA = L2_1
