L4_1 = "SCAVENGER_DIVE50_END@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3100011
L3_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "SYSOP_NPC_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "혼자인 편이 계획을 진행하기에 더 수월했을지도 모르지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "一人の方が計画を進めるには楽だったのかもしれない。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Maybe she had to be alone to carry out her plan."
L3_1.m_Talk_ENG = L4_1
L4_1 = "一個人說不定更好執行計畫呢！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เธออาจจะต้องอยู่คนเดียวเพื่อที่จะทำตามแผนให้สำเร็จ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Có lẽ cô ấy phải thực hiện kế hoạch một mình."
L3_1.m_Talk_VTN = L4_1
L4_1 = "一个人说不定也是她计划的一环。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Vielleicht musste sie allein sein, um ihren Plan auszuführen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Peut-être qu'elle avait besoin d'être seule pour mettre son plan à exécution ?"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "SCAVENGER_DIVE50_END@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3100011
L4_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "SYSOP_NPC_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "스캐빈저는 언제나 노예로 부릴 기술자들을 납치하고 다니잖아?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "スカベンジャーは頻繫に奴隷に使う技術者たちをさらっていくだろ？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "The Scavengers always look for technicians to abduct and enslave."
L4_1.m_Talk_ENG = L5_1
L5_1 = "清道夫不是一天到晚把研究人員綁架來當奴隸嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "สคาเวนเจอร์คอยจ้องจะลักพาตัวและเอาช่างเทคนิคไปใช้งานอยู่แล้ว"
L4_1.m_Talk_THA = L5_1
L5_1 = "Scavengers luôn tìm kiếm những kỹ thuật viên để bắt cóc và bắt làm nô lệ."
L4_1.m_Talk_VTN = L5_1
L5_1 = "清道夫一直到处绑架技术人员，当奴隶使唤不是嘛。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Die Scavenger entführen ja ständig Techniker zum Versklaven."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Et puis, les Scavengers sont toujours à la recherche d'ingénieurs à kidnapper et exploiter..."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
