L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3100011
L6_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "COLLECTOR_NPC_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "녀석이 스캐빈저에게 일부러 납치당해 준 거라고?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "奴がスカベンジャーにわざとさらわれたと？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You think she let the Scavengers abduct her, on purpose?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "你的意思是，她是故意被清道夫綁架的？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เธอคิดว่าด็อกเตอร์เอมเบอร์ตั้งใจให้ตัวเองถูกสคาเวนเจอร์ลักพาตัวเหรอ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô nghĩ rằng cô ấy cố tình để cho  Scavengers bắt cóc?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "你是说她是故意被清道夫绑架的？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Glaubst du, dass sie sich absichtlich von den Scavengern entführen lassen hat?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu veux dire... qu'elle se serait volontairement laissée enlever par les Scavengers ?"
L6_1.m_Talk_FRA = L7_1
