L9_1 = "SCAVENGER_DIVE50_END@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3100011
