L10_1 = "SCAVENGER_DIVE50_END@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3100011
L9_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "SYSOP_NPC_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "스캐빈저의 장비 수준이 어지간한 태스크포스를 뛰어넘기 시작한 것도 박사가 실종된 시기와 맞물려."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "スカベンジャーの装備水準が一般的なタスクフォースカンパニーを超え始めたのも、博士が失踪した時期と重なる。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It was around the same time the doctor disappeared that the Scavengers started using gear that was better than most TASKFORCE companies'."
L9_1.m_Talk_ENG = L10_1
L10_1 = "清道夫的裝備水準開始超越特遣勢力的時間點，正好就是博士失蹤的時候！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ใกล้ๆ ช่วงเวลาเดียวกับที่ด็อกเตอร์หายตัวไป พวกสคาเวนเจอร์ก็เริ่มใช้อุปกรณ์ที่ดีกว่าของบริษัททาสก์ฟอร์สส่วนใหญ่"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cũng vào khoảng thời gian tiến sĩ biến mất, Scavengers đã bắt đầu sử dụng thiết bị tốt hơn hầu hết các công ty TASKFORCE khác. "
L9_1.m_Talk_VTN = L10_1
L10_1 = "清道夫的装备水平突然超过一般特遣势力的时期，也跟博士失踪的时间对得上。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Das Niveau der Ausrüstungen bei den Scavengern hat jenes der TASKFORCE-Firmen übertroffen, kurz nachdem sie vermisst wurde."
L9_1.m_Talk_DEU = L10_1
L10_1 = "La disparition du professeur coïnciderait avec le moment où les Scavengers ont commencé à utiliser des équipements supérieurs à ceux employés par les entreprises TASKFORCE."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "SCAVENGER_DIVE50_END@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3100011
L10_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "SYSOP_NPC_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "그리고 몇 년 뒤엔 스캐빈저에 커다란 기계 로봇이 나타나 우두머리 노릇을 하기 시작했고."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そして、数年後にはスカベンジャーに巨大な機械ロボットが現れ、ボスとなっていた。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Then, a few years later, a gigantic robot showed up leading the Scavengers."
L10_1.m_Talk_ENG = L11_1
L11_1 = "然後幾年後，清道夫中出現的巨大機器人開始成為老大。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จากนั้นไม่กี่ปีต่อมา หุ่นยนต์ยักษ์ก็โผล่ขึ้นมานำสคาเวนเจอร์"
L10_1.m_Talk_THA = L11_1
L11_1 = "Chỉ một vài năm sau đó, một con robot khổng lồ đã xuất hiện ở Scavengers."
L10_1.m_Talk_VTN = L11_1
L11_1 = "而且几年后，清道夫开始出现大型机械机器人并占据了老大的位置。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Und weitere Jahre später tauchte ein riesiger Maschinenroboter bei den Scavengern auf und nannte sich ihr Boss."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Et puis quelques années plus tard, un robot gigantesque est apparu à leur tête."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
