L14_1 = "SCAVENGER_DIVE50_END@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3100011
L13_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "SYSOP_NPC_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "개인적인 이야기를 하나 하자면 난 내 아버지에게 세상에 우연 따위는 없다고 배웠지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "個人的な話だが、私は自分の父から世の中に偶然なんて存在しないと教わった。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "This is just my story, but my dad told me nothing in this world is a coincidence."
L13_1.m_Talk_ENG = L14_1
L14_1 = "這是我私底下跟妳說的，我從我父親身上學到的就是，天底下沒有任何事情是偶然的！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นี่ก็แค่ความคิดฉันนะ แต่พ่อฉันเคยบอกว่าในวงการนี้ ไม่มีอะไรเป็นเรื่องบังเอิญ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đây chỉ là câu chuyện của tôi, nhưng bố tôi nói với tôi rằng trên đời này không có gì là trùng hợp ngẫu nhiên."
L13_1.m_Talk_VTN = L14_1
L14_1 = "以我自己的经历来说，我从我父亲身上学到了一件事，那就是这世上没有偶然。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Darf ich kurz etwas Privates erzählen? Mein Vater hat mich gelehrt, dass es keine Zufälle auf der Welt gibt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Au risque d'en dire trop... Mon père m'a appris que rien, dans ce monde, n'arrivait par hasard."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SCAVENGER_DIVE50_END@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3100011
L14_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "SYSOP_NPC_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "그리고 아주 오랫동안…… 그것이 진실이라는 걸 겪어야 했어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そしてとても長い間……それが真実であることをみずから経験してきた。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "And over the years, his lesson has proved itself true over and over again."
L14_1.m_Talk_ENG = L15_1
L15_1 = "而且經過我長時間以來的驗證……這句話是真的沒錯。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "และตลอดหลายปีที่ผ่านมาก็พิสูจน์แล้วว่าบทเรียนของเขาเป็นความจริง"
L14_1.m_Talk_THA = L15_1
L15_1 = "Và trong những năm qua, bài học của ông đã được chứng minh hết lần này đến lần khác."
L14_1.m_Talk_VTN = L15_1
L15_1 = "而且很长一段时间的经历告诉我……确实如此。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Und über eine lange Zeit hinweg hat sich diese Lektion immer wieder bewahrheitet."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Avec les années, cette phrase s'est révélée remarquablement exacte."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SCAVENGER_DIVE50_END@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3100011
L15_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "SYSOP_NPC_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "그러니 스캐빈저가 수집하는 유물과 기술을 이용하려고 일부러 납치당한 미치광이가 있다는 건……"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "だから、スカベンジャーが収集する遺物と技術を利用しようと、わざと拉致されたイカれた人間がいるというのは……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "To me, it sounds plausible that some lunatic scientist let the Scavengers abduct her..."
L15_1.m_Talk_ENG = L16_1
L16_1 = "也就是，有個想利用清道夫收集到的遺物和技術，才故意被綁架的瘋子……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "สำหรับฉัน ฉันว่ามันก็เป็นไปได้ที่นักวิทยาศาสตร์สติเฟื่องสักคนจะจงใจให้สคาเวนเจอร์ลักพาตัว..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Một nhà khoa học mất trí nào đó bị Scavengers bắt cóc nghe có vẻ khá hợp lý đấy..."
L15_1.m_Talk_VTN = L16_1
L16_1 = "所以，为了使用清道夫收集的遗物和技术故意被绑架……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Deshalb klingt für mich die Geschichte, dass eine Verrückte sich absichtlich entführen lassen hat, um Zugriff zu den Relikten und Technologien zu bekommen, welche die Scavenger sammeln ..."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Une scientifique lunatique qui se serait volontairement rendue captive des Scavengers afin d'avoir accès à leur technologies et leurs artefacts ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SCAVENGER_DIVE50_END@216#Talk"
