L17_1 = "SYSOP_NPC_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "내겐 아주 그럴 듯한 말로 들리는군. "
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "私にはもっともらしい話に聞こえるね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "because she wanted their Artifacts and technology. "
L16_1.m_Talk_ENG = L17_1
L17_1 = "根據我的理解是這樣啦！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เพราะต้องการอาร์ติแฟ็กต์กับเทคโนโลยีของพวกเขา"
L16_1.m_Talk_THA = L17_1
L17_1 = "vì cô ấy đã rất thèm muốn Thần Khí và công nghệ của họ."
L16_1.m_Talk_VTN = L17_1
L17_1 = "是非常有可能的事情。 "
L16_1.m_Talk_SCN = L17_1
L17_1 = "durchaus plausibel."
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est une histoire qui me paraît plausible. "
L16_1.m_Talk_FRA = L17_1
