L21_1 = "UNIT_LAUGH"
L20_1.m_Face = L21_1
L21_1 = "COLLECTOR_NPC_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "그땐 설마 정말로 그런 미치광이가 있을까 했는데."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "あの時はまさか本当にそんな変わり者がいるのかと半信半疑だったが。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Back then, I didn't really believe him."
L20_1.m_Talk_ENG = L21_1
L21_1 = "那個時候，我還想說世界上真的有這種瘋子嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ตอนนั้นฉันไม่เชื่อที่เขาพูด"
L20_1.m_Talk_THA = L21_1
L21_1 = "Hồi đó, tôi đã không thực sự tin tưởng hắn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "那时候我还想真的会有那种疯子吗。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Damals habe ich bezweifelt, dass jemand wirklich so durchgeknallt sein kann."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Sur le moment, je ne l'ai pas cru."
L20_1.m_Talk_FRA = L21_1
