L21_1.m_Pos = "C"
L22_1 = "큭큭, 그보다 더한 미치광이였을 줄은 몰랐네?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ククク、それよりもさらに頭がおかしい人間だったとはね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Hah hah. And here, you're more lunatic than he thought."
L21_1.m_Talk_ENG = L22_1
L22_1 = "呵呵呵～沒想到瘋的程度還更厲害呢！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฮ่าๆ และแล้วคุณก็สติเฟื่องกว่าที่เขาคิด"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ha ha. Và ở đây, còn có tên điên cuồng hơn hắn nghĩ."
L21_1.m_Talk_VTN = L22_1
L22_1 = "呵呵，没想到你更加疯狂。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hihi, aber siehe da, du bist noch viel durchgeknallter."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hé hé. Lunatique, hein ? Encore plus qu'il ne l'avait imaginé..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
