L25_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "부하들로부터 대략의 전말은 파악했다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "部下から聞いておおよその顛末は把握している。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "My men told me a brief story."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我的手下有稍微跟我說一下來龍去脈，"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ลูกน้องฉันเล่าให้ฟังคร่าวๆ แล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Người của ta đã kể cho ta một câu chuyện ngắn."
L25_1.m_Talk_VTN = L26_1
L26_1 = "事情的始末我已经听我的部下说了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Meine Männer haben mir die Lage grob geschildert."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Mes hommes m'ont déjà fait un bref topo de la situation."
L25_1.m_Talk_FRA = L26_1
