L28_1 = "UNIT_PRIDE"
L27_1.m_Face = L28_1
L28_1 = "COLLECTOR_NPC_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "그냥 열성팬이 스타를 만나러 왔다고 생각해줘."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "お前の熱狂的なファンがスターに会いに来たという理由じゃダメかな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Let's say I'm an avid fan of yours."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你就把我當作是追星的瘋狂粉絲吧。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เอาเป็นว่าฉันเป็นแฟนพันธุ์แท้ของคุณก็แล้วกัน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Có thể nói tôi là một người hâm mộ cô cuồng nhiệt."
L27_1.m_Talk_VTN = L28_1
L28_1 = "你就当成是铁杆粉丝来看明星吧。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich bin ein großer Fan, die ihren Star sehen will."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Disons simplement que je suis une grande fan."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SCAVENGER_DIVE50_END@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3100011
L28_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "COLLECTOR_NPC_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "얼마 전에 당신의 작품을 체험할 기회가 있었거든."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "この前あんたの作品を体験する機会があったんだ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "A while ago, I had a chance to experience your handiwork."
L28_1.m_Talk_ENG = L29_1
L29_1 = "之前我有幸體驗到妳的作品。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ก่อนหน้านี้ฉันเคยได้สัมผัสกับผลงานของคุณ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Một thời gian trước, tôi đã có cơ hội để trải nghiệm tác phẩm của cô."
L28_1.m_Talk_VTN = L29_1
L29_1 = "因为不久前，我有幸体验了一把你的作品。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich hatte letztens die Chance, dein Werk zu erleben."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Il y a quelque temps, j'ai eu la chance d'essayer une de tes créations."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SCAVENGER_DIVE50_END@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3100011
L29_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
