L30_1 = "COLLECTOR_NPC_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "덕분에, 그 날 이후로 다른 기계들로는 만족 못하게 됐지 뭐야?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "おかげで、あの日以来他の機械じゃ満足できない身体になってしまってね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "And it's ruined other machines for me."
L29_1.m_Talk_ENG = L30_1
L30_1 = "托妳的福，從那之後任何機械都無法滿足我。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "และมันให้ฉันเลิกสนใจเครื่องจักรอื่นๆ ไปเลย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Và nó đã phá hỏng những máy móc khác của tôi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "从那之后，其他机械就不能让我满足了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Und seitdem ist es mir unmöglich geworden, zufrieden mit anderen Maschinen zu sein."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Et depuis... Les autres machines ne m'intéressent plus."
L29_1.m_Talk_FRA = L30_1
