L31_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L32_1 = "……널 알고 있다. 기계수집가."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "……お前のことは知っている、機械収集家。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I know you, Machine Collector."
L31_1.m_Talk_ENG = L32_1
L32_1 = "機械收藏家……我知道妳是誰。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันรู้จักคุณนะ ผู้สะสมเครื่องจักร"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ta biết cô, Nhà Sưu Tập Máy Móc."
L31_1.m_Talk_VTN = L32_1
L32_1 = "……我认识你，机械收藏家。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich kenne dich, Maschinensammlerin."
L31_1.m_Talk_DEU = L32_1
L32_1 = "J'ai entendu parler de toi, la Collectionneuse mécanique."
L31_1.m_Talk_FRA = L32_1
