L32_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L33_1 = "날 빼앗고 싶나?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私を奪いたいのか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Do you want to collect me?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "妳想把我搶走？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คุณอยากสะสมฉันเหรอ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô muốn thu thập ta ư?"
