L35_1 = "UNIT_LAUGH"
L34_1.m_Face = L35_1
L35_1 = "COLLECTOR_NPC_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "처음엔 당연히 그러려고 했는데, 마음이 바뀌었어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "最初はもちろんそうしようとしたが、気が変わった。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "At first, I did, but I've changed my mind."
L34_1.m_Talk_ENG = L35_1
L35_1 = "我原本是打算這樣沒錯，但我改變心意了。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ตอนแรกก็อยาก แต่ตอนนี้ฉันเปลี่ยนใจแล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Lúc đầu, đúng là thế, nhưng tôi đã thay đổi quyết định."
L34_1.m_Talk_VTN = L35_1
L35_1 = "一开始我当然也想那么做，不过后来我改主意了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Das hatte ich anfangs vor, aber ich habe es mir anders überlegt."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Au début c'était mon idée, mais j'ai changé d'avis."
L34_1.m_Talk_FRA = L35_1
