L36_1 = "COLLECTOR_NPC_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "난 순수한 기계에 흥미가 있을 뿐이야."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "私は純粋に機械に興味があるだけ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I'm only interested in pure machines."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我只對單純的機械有興趣。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันสนใจแค่เครื่องจักรเท่านั้น"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi chỉ quan tâm đến máy móc thuần túy."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我只对纯机械感兴趣。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich bin interessiert an Maschinen, das ist alles."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Seules les vraies machines m'intéressent."
L35_1.m_Talk_FRA = L36_1
