L37_1 = "COLLECTOR_NPC_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "인간의 뇌를 스튜로 만들어서 회로에 끼얹은 너 같은 반쪽짜리는 취향이 아니지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "人間の脳みそをシチューにして回路にぶっかけた、お前のような中途半端な奴は好みじゃない。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Not the half-baked kind like you, whose circuits are drenched in human brain stew."
L36_1.m_Talk_ENG = L37_1
L37_1 = "像妳這種用人腦改造再加上線路的東西我沒興趣！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่ใช่พวกกึ่งมนุษย์แบบคุณที่มีวงจรอยู่ในหม้อสมองมนุษย์"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không phải loại nửa nọ nửa kia như cô, với các bo mạch bị nhấn chìm trong dịch não người."
L36_1.m_Talk_VTN = L37_1
L37_1 = "像你这种把人类大脑植入电路里的半机械不是我的菜。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du bist leider nur halbbacken, weil ein menschliches Gehirn zu Eintopf gekocht und auf Schaltkreise gekippt wurde."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Pas les hybrides comme toi, aux circuits qui mijotent dans la cervelle humaine."
L36_1.m_Talk_FRA = L37_1
