L40_1 = "m_bFaceLoop"
L39_1[L40_1] = false
L40_1 = "네가 날 공격하려 했다면, 널 미련없이 진화의 밑거름으로 썼을 텐데 말이지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "お前が私を攻撃してきたなら、躊躇せずお前を進化の肥やしにしようとしたのだが。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "If you tried to attack me, I would have used you to further evolve myself without any qualms."
L39_1.m_Talk_ENG = L40_1
L40_1 = "妳要是攻擊我的話，我就可以把妳拿來當作進化的材料。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ถ้าคุณพยายามโจมตีฉัน ฉันจะใช้คุณเพื่อพัฒนาตัวเองต่อไปได้สบายๆ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Nếu cô cố gắng tấn công ta, ta sẽ sử dụng cô để tiến hóa hơn nữa mà không có bất kỳ sự e ngại nào."
L39_1.m_Talk_VTN = L40_1
L40_1 = "你试图攻击我的话，我就可以毫不留情地把你当成进化养料了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Falls du mich angegriffen hättest, hätte ich dich allerdings als Dünger für die Evolution verwendet, ohne zu Zögern."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Si tu avais essayé de m'attaquer, j'aurais pu t'utiliser sans regrets pour parfaire mon évolution."
L39_1.m_Talk_FRA = L40_1
