L42_1 = "스캐빈저의 우두머리 자릴 되찾고 싶은 거라면 그냥 가져."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "スカベンジャーのボスという肩書きが欲しいなら、くれてやる。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "If you want the Scavengers' leadership position back, it's yours."
L41_1.m_Talk_ENG = L42_1
L42_1 = "如果妳是想奪回清道夫老大的位置，那就拿去吧！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ถ้าคุณอยากได้ตำแหน่งหัวหน้าสคาเวนเจอร์คืนก็เชิญเลย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nếu cô muốn lấy lại vị trí lãnh đạo của Scavengers, của cô tất đấy."
L41_1.m_Talk_VTN = L42_1
L42_1 = "你要是想拿回清道夫老大的位置的话，尽管拿走。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Nimm dir deine Position als Boss der Scavenger zurück, wenn du willst."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Tu peux reprendre le contrôle des Scavengers, si ça te chante."
L41_1.m_Talk_FRA = L42_1
