L43_1 = "나도 뒤통수 노려보는 부하들은 필요 없으니까."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "俺だって隙ありゃ命を狙ってくる部下は要らねえ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I don't want to worry about being killed by my own men anymore."
L42_1.m_Talk_ENG = L43_1
L43_1 = "反正我也不想要一群整天想扯我後腿的手下！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันไม่อยากต้องกังวลว่าจะถูกลูกน้องของตัวเองฆ่าแล้ว"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi không muốn lo lắng về việc bị chính người của mình giết nữa."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我也不需要想在背后捅我刀子的手下。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich habe keine Schergen nötig, die mir in den Rücken fallen wollen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Devoir surveiller mes arrières en permanence parce que mes subalternes veulent ma peau, c'est pas mon truc."
L42_1.m_Talk_FRA = L43_1
