L43_1.m_fTalkTime = 0.03
L44_1 = "それより、一つ提案があるんだが……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "By the way, I've got a proposition that you might be interested in."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不過我有更好的提議……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ว่าแต่ ฉันมีข้อเสนอที่คุณอาจจะสนใจนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhân tiện, tôi có một đề xuất mà cô có thể quan tâm."
L43_1.m_Talk_VTN = L44_1
L44_1 = "比起那个，我有个好提议……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Übrigens habe ich einen guten Vorschlag für dich ..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Et puis, j'ai aussi une proposition qui pourrait t'intéresser."
