L47_1 = "난 너와 같은 인간이 아니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私はお前と同じ人間ではない。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I'm not a human like you."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我和妳不一樣。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันไม่ได้เป็นมนุษย์เหมือนคุณ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ta không phải là con người giống như vậy."
