L47_1 = "我跟你不一样，不是人类。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich bin kein Mensch, so wie du."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je ne suis pas comme toi, tu sais ?"
