L47_1.m_Pos = "C"
L48_1 = "이 몸을 얻은 뒤로는 인간으로서의 일 따윈 아무래도 상관없어졌어."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "この身を手に入れた瞬間から、人間としての考え方なんてどうでもいいものになった。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Since I've acquired this body, I stopped caring about human affairs."
L47_1.m_Talk_ENG = L48_1
L48_1 = "在我得到這副軀體後，人類的事情就已與我無關。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ตั้งแต่ได้ร่างนี้มา ฉันก็หยุดสนใจเรื่องกิจของมนุษย์"
L47_1.m_Talk_THA = L48_1
L48_1 = "Kể từ khi có được cơ thể này, ta đã ngừng quan tâm đến các vấn đề của con người."
L47_1.m_Talk_VTN = L48_1
L48_1 = "得到这具躯体后，作为人类的情感就全都没有了。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Seitdem ich diesen Körper erlangt habe, sind mir menschliche Angelegenheiten schnuppe."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Depuis que j'ai obtenu ce corps, j'ai cessé de m'intéresser aux affaires humaines."
L47_1.m_Talk_FRA = L48_1
