L48_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "신념이나 소원 같은 무가치한 것들은 <color=#ffd34c>나</color>라는 정의 앞에선 그저 말장난일 뿐이지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "信念や願いのような無価値なものは、<color=#ffd34c>私</color>という正義の前では言葉遊びに過ぎない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Meaningless concepts like faith and belief are just wordplay in the face of the justice that is <color=#ffd34c>me</color>."
L48_1.m_Talk_ENG = L49_1
L49_1 = "信念或是心願這種話，在<color=#ffd34c>我</color>聽來不過就是沒意義的笑話而已。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มโนทัศน์ที่ไร้ความหมายอย่างศรัทธาหรือความเชื่อก็เป็นแค่การเล่นคำสำหรับความยุติธรรม ซึ่งก็คือ<color=#ffd34c>ตัวฉัน</color>"
L48_1.m_Talk_THA = L49_1
L49_1 = "Những khái niệm vô nghĩa như niềm tin và tín ngưỡng chỉ là cách chơi chữ khi đối mặt với công lý là <color=#ffd34c>ta</color> thôi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "信念或心愿，这些毫无价值的东西，在<color=#ffd34c>我</color>的定义面前都只是文字游戏而已。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wertlose Dinge wie Glaube und Wunsch sind nichts weiter als Wortspiele im Angesicht von <color=#ffd34c>mir</color>, der Gerechtigkeit."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Croyances, désirs... Tout ceci n'est que futilité face à la justice que <color=#ffd34c>j'incarne</color>."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SCAVENGER_DIVE50_END@249#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3100011
L49_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "내 존재를 증명하는 것은 오직 영원한 진화 뿐이다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "私の存在を証明するのはただ一つ、永遠の進化のみ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Only continuous evolution can prove my existence."
L49_1.m_Talk_ENG = L50_1
L50_1 = "能夠證明我的存在的，唯有永遠的進化而已！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "มีเพียงวิวัฒนาการต่อเนื่องเท่านั้นที่จะพิสูจน์การมีตัวตนของฉันได้"
L49_1.m_Talk_THA = L50_1
L50_1 = "Chỉ có sự tiến hóa liên tục mới có thể chứng minh sự tồn tại của ta."
L49_1.m_Talk_VTN = L50_1
L50_1 = "能证明我存在的，只有永恒的进化。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Einzig die ewige Evolution belegt meine Existenz."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Mon existence à moi, elle n'est prouvée que par une chose : l'évolution perpétuelle."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SCAVENGER_DIVE50_END@250#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 250
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3100011
L50_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "만약 그 제안에 인간다운 공감이 필요하다면 무의미한 시도가 되겠지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "もしその提案に人間らしい共感が必要ならば、無意味な試みになるだろう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "If your proposition requires human sympathy, it won't even be worth listening to."
L50_1.m_Talk_ENG = L51_1
L51_1 = "如果妳的提議是需要人性的回應，那我勸妳還是省點力氣吧！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หากข้อเสนอของคุณต้องอาศัยความเห็นอกเห็นใจแบบมนุษย์ มันก็ไม่มีค่าควรฟังหรอก"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nếu đề xuất của cô đòi hỏi sự thông cảm của con người, thì nó thậm chí sẽ không đáng để lắng nghe."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如果你的提议需要人类之间的共鸣，那就是毫无意义的尝试。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Falls dein Vorschlag menschliche Empathie mit einbeschließt, wird er vergebens sein."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Alors si ta proposition implique une quelconque forme d'empathie humaine, tu perds ton temps."
L50_1.m_Talk_FRA = L51_1
