L10_1 = "SCAVENGER_DIVE50_END@259#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 259
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3100011
L9_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "RAUL_SCAVENGER_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "이야, 마취 하나 안 했는데 잘도 퍼질러자는구만."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "いやー、麻酔もしてないのによくそんな寝てられるな。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Geez, how could you sleep without a drop of anesthetics in you?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "喂，我又沒給你打麻醉，你會不會睡得太爽？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ให้ตายสิ นายหลับลงได้ไงโดยไม่ใช้ยา"
L9_1.m_Talk_THA = L10_1
L10_1 = "Geez, làm sao anh có thể ngủ được nếu không có một giọt thuốc mê trong người chứ?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "嘿嘿，连麻醉都没打，你睡得倒是挺香啊。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Herrje, du ratzt wie ein Kleinkind, sogar ganz ohne Betäubung."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Comment t'as pu dormir tout le temps alors que je t'ai même pas anesthésié ?"
L9_1.m_Talk_FRA = L10_1
