L12_1 = "SCAVENGER_DIVE50_END@261#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 261
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3100011
L11_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "ROJO_SCAVENGER_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "……뚫린 것만 메꾸랬더니, 또 뭔 짓을 한 거지?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……空いた穴を埋めろと言ったはずなんだが、また何をしてくれたんだ？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I asked you to just mend the holes. What did you do to me this time?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "……我叫你把破的地方補好就好，你又再給我亂弄什麼？！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ผมแค่ขอให้นายซ่อมจุดที่เป็นรู คราวนี้ทำอะไรกับผมล่ะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi chỉ yêu cầu cậu vá các lỗ. Lần này cậu đã làm gì tôi vậy?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "……我就让你把洞给我补上，你又做什么了？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du solltest doch nur die Lecks kitten. Was hast du wieder angestellt?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je t'ai juste demandé de reboucher les trous. Qu'est-ce que tu m'as fait, encore ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SCAVENGER_DIVE50_END@262#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 262
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3100011
L12_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "RAUL_SCAVENGER_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "아, 좀 허전해 보이길래 심장을 하나 더 달았어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あ、ちょっと寂しく見えたから心臓をもう一つ付けてやったぞ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Ah, your chest looked so vacant that I added a heart."
L12_1.m_Talk_ENG = L13_1
L13_1 = "唉唷～看起來有點空虛嘛！我就又裝了顆心臟囉！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อ๋อ อกนายดูว่างมาก ผมเลยเพิ่มหัวใจเข้าไป"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ah, ngực của anh trông trống rỗng đến nỗi tôi đã phải thêm một trái tim."
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊，我看洞里空荡荡的，就又多装了一个心脏。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ach, du hast so leer ausgesehen, dass ich noch ein weiteres Herz angebracht habe."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ton torse paraissait trop vide, alors j'y ai ajouté un cœur."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SCAVENGER_DIVE50_END@263#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 263
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3100011
L13_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "RAUL_SCAVENGER_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "살아 있는 거 보니, 작동엔 문제없어 보이네."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "まあ今生きているってことは、作動に問題はなさそうだな。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You're still alive, so it must be working fine."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我看你現在還有力氣罵人，那運作應該也沒問題吧！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นายยังมีชีวิต แปลว่ามันได้ผล"
L13_1.m_Talk_THA = L14_1
L14_1 = "Anh vẫn còn sống, vậy là nó hẳn phải hoạt động tốt."
L13_1.m_Talk_VTN = L14_1
L14_1 = "看你现在活蹦乱跳的样子，运转应该没问题。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Du lebst noch, also scheint es zu funktionieren."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Si tu es encore en vie, c'est que ça à du marcher."
L13_1.m_Talk_FRA = L14_1
