L17_1 = "SCAVENGER_DIVE50_END@266#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3100011
L16_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "ROJO_SCAVENGER_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "L"
L16_1.m_Pos = L17_1
L17_1 = "잘 모르겠군. 번거롭게 심장이 세 개씩이나 필요한 건가?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "よくわからんな。心臓なんて3つも必要なのか？　煩わしい。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I don't know. Do I really need three hearts?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "我真猜不透你，有誰會需要三顆心臟？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ไม่รู้สิ ผมจำเป็นต้องมีหัวใจสามดวงจริงๆ เหรอ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi không biết. Tôi có thực sự cần ba trái tim không?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "不知道，不过至于需要三个心脏吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich weiß nicht. Brauche ich echt drei Herzen?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Franchement, est-ce que j'ai vraiment besoin d'avoir 3 cœurs ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SCAVENGER_DIVE50_END@267#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 267
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3100011
L17_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "RAUL_SCAVENGER_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "R"
L17_1.m_Pos = L18_1
L18_1 = "이번에 추가한 건 인공장기가 아니라 전자식이야. 그 여자가 쓰는 로봇 기생충이 꽤 쓸 만하더라고."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今回追加したのは人工臓器じゃなくて電子式だ。あの女が使うロボット寄生虫が中々使えるもんでね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The one I've added this time isn't artificial; it's electrically-operated. That woman's robot parasites turned out to be pretty useful."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這次裝的不是人工器官，是電子的好嗎！那女人使用的機器寄生蟲還滿不錯的嘛～"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ที่เพิ่มเข้าไปไม่ใช่ของปลอมนะ แต่ทำงานด้วยไฟฟ้า ปรสิตหุ่นยนต์ของผู้หญิงคนนั้นมีประโยชน์ใช้ได้เลย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cái mà tôi đã thêm lần này không phải là nhân tạo; nó hoạt động bằng điện. Ký sinh trùng robot của cô gái đó đó hóa ra lại khá hữu ích."
L17_1.m_Talk_VTN = L18_1
L18_1 = "这次新加的心脏是电子式的，不是人工器官。那个女人用的机器人寄生虫还挺有用。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Das von diesmal ist keine Prothese, sondern es ist elektronisch. Die Roboterparasiten von der Frau sind recht gut."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh, mais celui-ci n'est pas artificiel, il est électronique. Les robots parasites de l'autre fille sont terriblement efficaces."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "SCAVENGER_DIVE50_END@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3100011
L18_1.m_CutScenStrID = "SCAVENGER_DIVE50_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "RAUL_SCAVENGER_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "R"
L18_1.m_Pos = L19_1
L19_1 = "상처가 생기면 기생충이 혈류를 타고 흘러가서 빠르게 땜빵해 줄 거야."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "傷ができたら寄生虫が血流に乗って流れていき、素早く傷を埋めてくれる。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Whenever you're wounded, the parasites will quickly flow through your bloodstream and mend you."
L18_1.m_Talk_ENG = L19_1
L19_1 = "有傷口的話，寄生蟲就會順著血液流動快速進行修補喔！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ทุกครั้งที่นายได้รับบาดเจ็บ ปรสิตจะวิ่งเข้าไปในกระแสเลือดของนาย แล้วก็ซ่อมแซมร่างกายนาย"
L18_1.m_Talk_THA = L19_1
L19_1 = "Bất cứ khi nào anh bị thương, ký sinh trùng sẽ nhanh chóng di chuyển trong máu và sửa chữa."
L18_1.m_Talk_VTN = L19_1
L19_1 = "受伤时寄生虫会顺着血液流过去，快速修补伤口。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Falls du verwundet wirst, schwimmen die Parasiten durch deine Blutbahnen und kitten schnell die Wunden für dich."
L18_1.m_Talk_DEU = L19_1
L19_1 = "En cas de blessure, les parasites circuleront dans tes vaisseaux sanguins pour soigner immédiatement la plaie."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
