L20_1 = "但如果是頭掉了的話……？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่ถ้านายเสียหัวไป..."
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng nếu anh mất đầu-"
