L20_1 = "脑袋掉了的话……？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Und wenn meine Birne wegfliegt ...?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Par contre, si tu perds ta tête..."
